def sequentialthinking(thought, thoughtNumber, totalThoughts, nextThoughtNeeded, isRevision=None, revisesThought=None, branchFromThought=None, branchId=None, needsMoreThoughts=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Basic validation ---
    if not isinstance(thought, str) or not thought.strip():
        return _err("VALIDATION_ERROR", "thought must be a non-empty string")
    if not isinstance(nextThoughtNeeded, bool):
        return _err("VALIDATION_ERROR", "nextThoughtNeeded must be boolean")
    if not isinstance(thoughtNumber, (int, float)) or int(thoughtNumber) != thoughtNumber or thoughtNumber < 1:
        return _err("VALIDATION_ERROR", "thoughtNumber must be an integer >= 1")
    if not isinstance(totalThoughts, (int, float)) or int(totalThoughts) != totalThoughts or totalThoughts < 1:
        return _err("VALIDATION_ERROR", "totalThoughts must be an integer >= 1")
    thoughtNumber = int(thoughtNumber)
    totalThoughts = int(totalThoughts)

    if isRevision is None:
        isRevision = False
    if not isinstance(isRevision, bool):
        return _err("VALIDATION_ERROR", "isRevision must be boolean when provided")

    if revisesThought is not None:
        if not isinstance(revisesThought, (int, float)) or int(revisesThought) != revisesThought or revisesThought < 1:
            return _err("VALIDATION_ERROR", "revisesThought must be an integer >= 1")
        revisesThought = int(revisesThought)

    if branchFromThought is not None:
        if not isinstance(branchFromThought, (int, float)) or int(branchFromThought) != branchFromThought or branchFromThought < 1:
            return _err("VALIDATION_ERROR", "branchFromThought must be an integer >= 1")
        branchFromThought = int(branchFromThought)

    if branchId is not None and (not isinstance(branchId, str) or not branchId.strip()):
        return _err("VALIDATION_ERROR", "branchId must be a non-empty string when provided")
    if needsMoreThoughts is not None and not isinstance(needsMoreThoughts, bool):
        return _err("VALIDATION_ERROR", "needsMoreThoughts must be boolean when provided")

    if isRevision and revisesThought is None:
        return _err("VALIDATION_ERROR", "revisesThought is required when isRevision=true")

    # --- Load datastore ---
    sessions = _load("reasoning_sessions.json")
    events = _load("session_events.json")

    # --- Ambient auth: no explicit credentials in this API; assume authorized. ---

    # --- Determine / upsert session (no external_id in tool params; treat branchId as tool-provided session identifier) ---
    # Vendor rule: upsert by (session_type, external_id) when an external identifier is included.
    # This tool does not include sessionId; we use branchId when present, otherwise a stable default.
    external_id = (branchId.strip() if isinstance(branchId, str) and branchId.strip() else "default")
    session_type = "sequential_thinking"
    session = None
    for s in sessions:
        if s.get("session_type") == session_type and s.get("external_id") == external_id:
            session = s
            break

    if session is None:
        sid = f"rs_{uuid.uuid4().hex}"
        session = {
            "id": sid,
            "session_type": session_type,
            "external_id": external_id,
            "title": None,
            "iteration": 0,
            "stage": None,
            "status": "active",
            "next_action_needed": bool(nextThoughtNeeded),
            "context_text": None,
            "stakeholders": None,
            "constraints_text": None,
            "time_horizon": None,
            "risk_tolerance": None,
            "analysis_type": None,
            "overall_confidence": None,
            "uncertainty_areas": None,
            "recommended_approach": None,
            "diagram_type": None,
            "final_text": None,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(session)
    else:
        session["next_action_needed"] = bool(nextThoughtNeeded)
        session["updated_at"] = now

    # --- Enforce ordering/integrity constraints ---
    session_id = session["id"]

    # Collect existing events for this session
    sess_events = [e for e in events if e.get("session_id") == session_id and e.get("tool_name") == "sequentialthinking"]
    # Validate revisesThought exists within this session (regardless of branch fields; tool doesn't have explicit branch model in schema)
    if isRevision:
        exists = False
        for e in sess_events:
            if e.get("event_type") in ("thought", "revision", "branch"):
                pn = e.get("payload", {}).get("thoughtNumber")
                if pn == revisesThought and e.get("payload", {}).get("isRevision") is not True:
                    # allow revising a base thought (not a revision of a revision); accept either way? keep permissive:
                    exists = True
                    break
                if pn == revisesThought:
                    exists = True
                    break
        if not exists:
            return _err("VALIDATION_ERROR", "revisesThought must refer to an existing thoughtNumber within the same session", revisesThought=revisesThought)

    # Reject duplicate thoughtNumber within same "branch context" (approximate: same external_id + same branchFromThought + same branchId)
    for e in sess_events:
        p = e.get("payload", {}) or {}
        if p.get("thoughtNumber") == thoughtNumber:
            if (p.get("branchId") or None) == (branchId or None) and (p.get("branchFromThought") or None) == (branchFromThought or None):
                return _err("CONFLICT", "Duplicate thoughtNumber within the same branch context", thoughtNumber=thoughtNumber, branchId=branchId, branchFromThought=branchFromThought)

    # Determine event_type
    if isRevision:
        event_type = "revision"
    elif branchId is not None or branchFromThought is not None:
        event_type = "branch"
    else:
        event_type = "thought"

    # Compute next sequence_number for session (all tools)
    max_seq = 0
    for e in events:
        if e.get("session_id") == session_id:
            sn = e.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn
    seq = max_seq + 1

    # iteration: use session.iteration (non-negative)
    iteration = session.get("iteration")
    if not isinstance(iteration, int) or iteration < 0:
        session["iteration"] = 0
        iteration = 0

    payload = {
        "thought": thought,
        "thoughtNumber": thoughtNumber,
        "totalThoughts": totalThoughts,
        "nextThoughtNeeded": bool(nextThoughtNeeded),
        "isRevision": bool(isRevision),
        "revisesThought": revisesThought,
        "branchFromThought": branchFromThought,
        "branchId": branchId,
        "needsMoreThoughts": needsMoreThoughts,
    }

    # Append event
    ev_id = f"ev_{uuid.uuid4().hex}"
    ev = {
        "id": ev_id,
        "session_id": session_id,
        "tool_name": "sequentialthinking",
        "event_type": event_type,
        "sequence_number": seq,
        "iteration": iteration,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev)

    # Persist
    _save("reasoning_sessions.json", sessions)
    _save("session_events.json", events)

    # Build updated session state: include latest thought payload and session flags
    # "needsMoreThoughts" is included in payload; nextThoughtNeeded drives next_action_needed
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "session": session,
        "event": ev,
        "state": {
            "thoughtNumber": thoughtNumber,
            "totalThoughts": totalThoughts,
            "nextThoughtNeeded": bool(nextThoughtNeeded),
            "needsMoreThoughts": needsMoreThoughts,
            "branchId": branchId,
            "branchFromThought": branchFromThought,
            "isRevision": bool(isRevision),
            "revisesThought": revisesThought,
        },
        "meta": {
            "latency_ms": latency_ms,
            "timestamp": now,
        },
    }

def mentalmodel(modelName, problem, steps=None, reasoning=None, conclusion=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    allowed = {
        "first_principles",
        "opportunity_cost",
        "error_propagation",
        "rubber_duck",
        "pareto_principle",
        "occams_razor",
    }
    if not isinstance(modelName, str) or modelName not in allowed:
        return _err("VALIDATION_ERROR", "modelName must be one of the supported enum values", allowed=sorted(list(allowed)))
    if not isinstance(problem, str) or not problem.strip():
        return _err("VALIDATION_ERROR", "problem must be a non-empty string")

    if steps is not None:
        if not isinstance(steps, list) or any((not isinstance(x, str)) for x in steps):
            return _err("VALIDATION_ERROR", "steps must be an array of strings when provided")
    if reasoning is not None and not isinstance(reasoning, str):
        return _err("VALIDATION_ERROR", "reasoning must be a string when provided")
    if conclusion is not None and not isinstance(conclusion, str):
        return _err("VALIDATION_ERROR", "conclusion must be a string when provided")

    sessions = _load("reasoning_sessions.json")
    events = _load("session_events.json")

    # Stateless advisory tool, but persisted as session_events.
    # No session id parameter; create/use a default session for this tool family.
    session_type = "metacognitive_monitoring"  # tool family closest? but rule says mentalmodel is separate tool_name; store as its own session_type? not in enum.
    # Since reasoning_sessions.session_type enum doesn't include "mentalmodel", store under sequential_thinking? No.
    # Use "structured_argumentation"? Also no.
    # Best fit: create a "sequential_thinking" session would be wrong; instead reuse allowed enum "metacognitive_monitoring" is also wrong.
    # Avoid violating enum by using "sequential_thinking"? That pollutes. We will attach to an existing valid session if present; else use sequential_thinking default.
    session = None
    for s in sessions:
        if s.get("session_type") == "sequential_thinking" and s.get("external_id") == "advisory":
            session = s
            break
    if session is None:
        sid = f"rs_{uuid.uuid4().hex}"
        session = {
            "id": sid,
            "session_type": "sequential_thinking",
            "external_id": "advisory",
            "title": "Advisory Tools",
            "iteration": 0,
            "stage": None,
            "status": "active",
            "next_action_needed": False,
            "context_text": None,
            "stakeholders": None,
            "constraints_text": None,
            "time_horizon": None,
            "risk_tolerance": None,
            "analysis_type": None,
            "overall_confidence": None,
            "uncertainty_areas": None,
            "recommended_approach": None,
            "diagram_type": None,
            "final_text": None,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(session)
    else:
        session["updated_at"] = now

    session_id = session["id"]

    max_seq = 0
    for e in events:
        if e.get("session_id") == session_id:
            sn = e.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn
    seq = max_seq + 1

    payload = {
        "modelName": modelName,
        "problem": problem,
        "steps": steps,
        "reasoning": reasoning,
        "conclusion": conclusion,
    }

    ev = {
        "id": f"ev_{uuid.uuid4().hex}",
        "session_id": session_id,
        "tool_name": "mentalmodel",
        "event_type": "model_application",
        "sequence_number": seq,
        "iteration": int(session.get("iteration") or 0),
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev)

    _save("reasoning_sessions.json", sessions)
    _save("session_events.json", events)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "session": session,
        "event": ev,
        "meta": {"latency_ms": latency_ms, "timestamp": now},
    }

def debuggingapproach(approachName, issue, steps=None, findings=None, resolution=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Minimal request logging infra (best-effort; schema not provided).
    def _log(status, tool_name="debuggingapproach", extra=None):
        extra = extra or {}
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool": tool_name,
            "status": status,
            "timestamp": now,
            "latency_ms": int((time.time() - start) * 1000),
            **extra,
        }
        fn = "request_logs.json"
        data = _load(fn)
        if not isinstance(data, list):
            data = []
        data.append(row)
        _save(fn, data)

    # Quota/rate limiting (schema not provided): enforce only if limits file exists.
    def _enforce_limits():
        limits = _load("service_limits.json")
        if not limits or not isinstance(limits, dict):
            return None
        # rate_limit_per_minute, quota_per_day
        rlm = limits.get("rate_limit_per_minute")
        qpd = limits.get("quota_per_day")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        # Parse timestamps in our own format; ignore unparsable
        def _parse(ts):
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow().replace(microsecond=0)
        if isinstance(rlm, int) and rlm >= 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse(r.get("timestamp", ""))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= rlm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(qpd, int) and qpd >= 0:
            cutoff = now_dt - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                ts = _parse(r.get("timestamp", ""))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", extra={"error_code": lim_err["error"]["code"]})
        return lim_err

    allowed = {
        "binary_search",
        "reverse_engineering",
        "divide_conquer",
        "backtracking",
        "cause_elimination",
        "program_slicing",
    }

    # Validate
    if not isinstance(approachName, str) or approachName not in allowed:
        e = _err("VALIDATION_ERROR", "Invalid approachName", field="approachName", allowed=sorted(list(allowed)))
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if not isinstance(issue, str) or not issue.strip():
        e = _err("VALIDATION_ERROR", "issue must be a non-empty string", field="issue")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if steps is not None:
        if not isinstance(steps, list) or any(not isinstance(x, str) for x in steps):
            e = _err("VALIDATION_ERROR", "steps must be an array of strings", field="steps")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
    if findings is not None and not isinstance(findings, str):
        e = _err("VALIDATION_ERROR", "findings must be a string", field="findings")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if resolution is not None and not isinstance(resolution, str):
        e = _err("VALIDATION_ERROR", "resolution must be a string", field="resolution")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    # Persist as a stateless advisory session_event; create a synthetic session for auditability.
    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    external_id = "debug:" + uuid.uuid4().hex  # tool has no external id; generate per call
    session_type = "structured_argumentation"  # not ideal, but schema enums don't include debugging; use events tool_name anyway

    # Pick a legal session_type: best fit is "metacognitive_monitoring" or "sequential_thinking" etc.
    # Use metacognitive_monitoring to keep audit grouping.
    session_type = "metacognitive_monitoring"

    sid = None
    for s in sessions:
        if s.get("session_type") == session_type and s.get("external_id") == external_id:
            sid = s.get("id")
            break

    if sid is None:
        sid = "rs_" + uuid.uuid4().hex
        sessions.append(
            {
                "id": sid,
                "session_type": session_type,
                "external_id": external_id,
                "title": "Debugging: " + issue.strip()[:80],
                "iteration": 0,
                "stage": None,
                "status": "active",
                "next_action_needed": False,
                "context_text": issue,
                "stakeholders": None,
                "constraints_text": None,
                "time_horizon": None,
                "risk_tolerance": None,
                "analysis_type": None,
                "overall_confidence": None,
                "uncertainty_areas": None,
                "recommended_approach": None,
                "diagram_type": None,
                "final_text": None,
                "created_at": now,
                "updated_at": now,
            }
        )
    else:
        for s in sessions:
            if s.get("id") == sid:
                s["updated_at"] = now
                s["context_text"] = issue
                break

    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []

    # sequence number monotonic per session
    max_seq = 0
    for ev in events:
        if ev.get("session_id") == sid:
            sn = ev.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn

    payload = {
        "approachName": approachName,
        "issue": issue,
        "steps": steps if steps is not None else None,
        "findings": findings if findings is not None else None,
        "resolution": resolution if resolution is not None else None,
    }

    ev_row = {
        "id": "ev_" + uuid.uuid4().hex,
        "session_id": sid,
        "tool_name": "debuggingapproach",
        "event_type": "debugging_application",
        "sequence_number": max_seq + 1,
        "iteration": 0,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev_row)

    _save("reasoning_sessions.json", sessions)
    _save("session_events.json", events)

    body = {
        "session": next(s for s in sessions if s["id"] == sid),
        "event": ev_row,
        "debuggingArtifact": payload,
    }
    _log("ok")
    return body

def collaborativereasoning(topic, personas, contributions, stage, activePersonaId, sessionId, iteration, nextContributionNeeded, nextPersonaId=None, consensusPoints=None, disagreements=None, keyInsights=None, openQuestions=None, finalRecommendation=None, suggestedContributionTypes=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts[:-1] if ts.endswith("Z") else ts
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    def _log(status, error=None, extra=None):
        # Optional observable dynamics: only if service has a request log collection.
        try:
            path = os.path.join(_DB, "request_logs.json")
            if not os.path.exists(path):
                return
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": _new_id("ct_req"),
                "endpoint": "collaborativereasoning",
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(extra, dict):
                row.update(extra)
            if isinstance(error, dict):
                row["error"] = error
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    def _enforce_limits():
        try:
            limits_path = os.path.join(_DB, "service_limits.json")
            logs_path = os.path.join(_DB, "request_logs.json")
            if not (os.path.exists(limits_path) and os.path.exists(logs_path)):
                return None
            limits = _load("service_limits.json")
            if not isinstance(limits, dict):
                return None
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []

            rlm = limits.get("rate_limit_per_minute")
            qpd = limits.get("quota_per_day")

            if isinstance(rlm, int) and rlm >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    dt = _parse_ts(r.get("timestamp"))
                    if dt and dt >= cutoff:
                        cnt += 1
                if cnt >= rlm:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")

            if isinstance(qpd, int) and qpd >= 0:
                day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    dt = _parse_ts(r.get("timestamp"))
                    if dt and dt >= day_start:
                        cnt += 1
                if cnt >= qpd:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            return None
        except Exception:
            return None

    # ---- Validate inputs (relax: accept any strings, only enforce schema/business rules) ----
    allowed_stage = {"problem-definition", "ideation", "critique", "integration", "decision", "reflection"}
    allowed_types = {"observation", "question", "insight", "concern", "suggestion", "challenge", "synthesis"}

    if not isinstance(topic, str) or not topic:
        e = _err("VALIDATION_ERROR", "topic must be a non-empty string.")
        _log("error", e["error"])
        return e
    if not isinstance(sessionId, str) or not sessionId:
        e = _err("VALIDATION_ERROR", "sessionId must be a non-empty string.")
        _log("error", e["error"])
        return e
    if stage not in allowed_stage:
        e = _err("VALIDATION_ERROR", "stage is invalid.", allowed=list(sorted(allowed_stage)))
        _log("error", e["error"])
        return e
    if not isinstance(activePersonaId, str) or not activePersonaId:
        e = _err("VALIDATION_ERROR", "activePersonaId must be a non-empty string.")
        _log("error", e["error"])
        return e
    if nextPersonaId is not None and (not isinstance(nextPersonaId, str) or not nextPersonaId):
        e = _err("VALIDATION_ERROR", "nextPersonaId must be a non-empty string when provided.")
        _log("error", e["error"])
        return e

    if not isinstance(iteration, (int, float)) or int(iteration) != iteration or int(iteration) < 0:
        e = _err("VALIDATION_ERROR", "iteration must be an integer >= 0.")
        _log("error", e["error"])
        return e
    iteration = int(iteration)

    if not isinstance(nextContributionNeeded, bool):
        e = _err("VALIDATION_ERROR", "nextContributionNeeded must be boolean.")
        _log("error", e["error"])
        return e

    if not isinstance(personas, list):
        e = _err("VALIDATION_ERROR", "personas must be an array.")
        _log("error", e["error"])
        return e
    if not isinstance(contributions, list):
        e = _err("VALIDATION_ERROR", "contributions must be an array.")
        _log("error", e["error"])
        return e

    # Validate personas structure
    persona_ids = set()
    for i, p in enumerate(personas):
        if not isinstance(p, dict):
            e = _err("VALIDATION_ERROR", f"personas[{i}] must be an object.")
            _log("error", e["error"])
            return e
        for k in ("id", "name", "expertise", "background", "perspective", "biases", "communication"):
            if k not in p:
                e = _err("VALIDATION_ERROR", f"personas[{i}].{k} is required.")
                _log("error", e["error"])
                return e
        if not isinstance(p["id"], str) or not p["id"]:
            e = _err("VALIDATION_ERROR", f"personas[{i}].id must be a non-empty string.")
            _log("error", e["error"])
            return e
        if p["id"] in persona_ids:
            e = _err("VALIDATION_ERROR", f"Duplicate personas[].id: {p['id']}")
            _log("error", e["error"])
            return e
        persona_ids.add(p["id"])
        if not isinstance(p["name"], str) or not p["name"]:
            e = _err("VALIDATION_ERROR", f"personas[{i}].name must be a non-empty string.")
            _log("error", e["error"])
            return e
        if not isinstance(p["expertise"], list) or any(not isinstance(x, str) for x in p["expertise"]):
            e = _err("VALIDATION_ERROR", f"personas[{i}].expertise must be an array of strings.")
            _log("error", e["error"])
            return e
        if not isinstance(p["biases"], list) or any(not isinstance(x, str) for x in p["biases"]):
            e = _err("VALIDATION_ERROR", f"personas[{i}].biases must be an array of strings.")
            _log("error", e["error"])
            return e
        if not isinstance(p["background"], str) or not p["background"]:
            e = _err("VALIDATION_ERROR", f"personas[{i}].background must be a non-empty string.")
            _log("error", e["error"])
            return e
        if not isinstance(p["perspective"], str) or not p["perspective"]:
            e = _err("VALIDATION_ERROR", f"personas[{i}].perspective must be a non-empty string.")
            _log("error", e["error"])
            return e
        comm = p["communication"]
        if not isinstance(comm, dict):
            e = _err("VALIDATION_ERROR", f"personas[{i}].communication must be an object.")
            _log("error", e["error"])
            return e
        if "style" not in comm or "tone" not in comm:
            e = _err("VALIDATION_ERROR", f"personas[{i}].communication.style and .tone are required.")
            _log("error", e["error"])
            return e
        if not isinstance(comm["style"], str) or not comm["style"]:
            e = _err("VALIDATION_ERROR", f"personas[{i}].communication.style must be a non-empty string.")
            _log("error", e["error"])
            return e
        if not isinstance(comm["tone"], str) or not comm["tone"]:
            e = _err("VALIDATION_ERROR", f"personas[{i}].communication.tone must be a non-empty string.")
            _log("error", e["error"])
            return e

    # Validate contributions structure (persona existence checked after upsert too)
    for i, c in enumerate(contributions):
        if not isinstance(c, dict):
            e = _err("VALIDATION_ERROR", f"contributions[{i}] must be an object.")
            _log("error", e["error"])
            return e
        for k in ("personaId", "content", "type", "confidence"):
            if k not in c:
                e = _err("VALIDATION_ERROR", f"contributions[{i}].{k} is required.")
                _log("error", e["error"])
                return e
        if not isinstance(c["personaId"], str) or not c["personaId"]:
            e = _err("VALIDATION_ERROR", f"contributions[{i}].personaId must be a non-empty string.")
            _log("error", e["error"])
            return e
        if not isinstance(c["content"], str) or not c["content"]:
            e = _err("VALIDATION_ERROR", f"contributions[{i}].content must be a non-empty string.")
            _log("error", e["error"])
            return e
        if c["type"] not in allowed_types:
            e = _err("VALIDATION_ERROR", f"contributions[{i}].type is invalid.", allowed=list(sorted(allowed_types)))
            _log("error", e["error"])
            return e
        conf = c["confidence"]
        if not isinstance(conf, (int, float)) or conf < 0 or conf > 1:
            e = _err("VALIDATION_ERROR", f"contributions[{i}].confidence must be within [0,1].")
            _log("error", e["error"])
            return e
        if "referenceIds" in c and c["referenceIds"] is not None:
            if not isinstance(c["referenceIds"], list) or any(not isinstance(x, str) for x in c["referenceIds"]):
                e = _err("VALIDATION_ERROR", f"contributions[{i}].referenceIds must be an array of strings when provided.")
                _log("error", e["error"])
                return e

    # Validate optional lists/objects lightly
    if consensusPoints is not None and (not isinstance(consensusPoints, list) or any(not isinstance(x, str) for x in consensusPoints)):
        e = _err("VALIDATION_ERROR", "consensusPoints must be an array of strings when provided.")
        _log("error", e["error"])
        return e
    if keyInsights is not None and (not isinstance(keyInsights, list) or any(not isinstance(x, str) for x in keyInsights)):
        e = _err("VALIDATION_ERROR", "keyInsights must be an array of strings when provided.")
        _log("error", e["error"])
        return e
    if openQuestions is not None and (not isinstance(openQuestions, list) or any(not isinstance(x, str) for x in openQuestions)):
        e = _err("VALIDATION_ERROR", "openQuestions must be an array of strings when provided.")
        _log("error", e["error"])
        return e
    if finalRecommendation is not None and not isinstance(finalRecommendation, str):
        e = _err("VALIDATION_ERROR", "finalRecommendation must be a string when provided.")
        _log("error", e["error"])
        return e
    if suggestedContributionTypes is not None:
        if not isinstance(suggestedContributionTypes, list) or any(x not in allowed_types for x in suggestedContributionTypes):
            e = _err("VALIDATION_ERROR", "suggestedContributionTypes must be an array of allowed contribution type strings when provided.", allowed=list(sorted(allowed_types)))
            _log("error", e["error"])
            return e
    if disagreements is not None:
        if not isinstance(disagreements, list):
            e = _err("VALIDATION_ERROR", "disagreements must be an array when provided.")
            _log("error", e["error"])
            return e
        for di, d in enumerate(disagreements):
            if not isinstance(d, dict) or "topic" not in d or "positions" not in d:
                e = _err("VALIDATION_ERROR", f"disagreements[{di}] must contain topic and positions.")
                _log("error", e["error"])
                return e
            if not isinstance(d["topic"], str) or not d["topic"]:
                e = _err("VALIDATION_ERROR", f"disagreements[{di}].topic must be a non-empty string.")
                _log("error", e["error"])
                return e
            if not isinstance(d["positions"], list):
                e = _err("VALIDATION_ERROR", f"disagreements[{di}].positions must be an array.")
                _log("error", e["error"])
                return e
            for pi, pos in enumerate(d["positions"]):
                if not isinstance(pos, dict):
                    e = _err("VALIDATION_ERROR", f"disagreements[{di}].positions[{pi}] must be an object.")
                    _log("error", e["error"])
                    return e
                for k in ("personaId", "position", "arguments"):
                    if k not in pos:
                        e = _err("VALIDATION_ERROR", f"disagreements[{di}].positions[{pi}].{k} is required.")
                        _log("error", e["error"])
                        return e
                if not isinstance(pos["personaId"], str) or not pos["personaId"]:
                    e = _err("VALIDATION_ERROR", f"disagreements[{di}].positions[{pi}].personaId must be a non-empty string.")
                    _log("error", e["error"])
                    return e
                if not isinstance(pos["position"], str) or not pos["position"]:
                    e = _err("VALIDATION_ERROR", f"disagreements[{di}].positions[{pi}].position must be a non-empty string.")
                    _log("error", e["error"])
                    return e
                if not isinstance(pos["arguments"], list) or any(not isinstance(x, str) for x in pos["arguments"]):
                    e = _err("VALIDATION_ERROR", f"disagreements[{di}].positions[{pi}].arguments must be an array of strings.")
                    _log("error", e["error"])
                    return e

    limit_err = _enforce_limits()
    if limit_err is not None:
        _log("error", limit_err["error"])
        return limit_err

    # ---- Upsert reasoning_session by (session_type, external_id) ----
    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []
    personas_rows = _load("collaboration_personas.json")
    if not isinstance(personas_rows, list):
        personas_rows = []

    sess = None
    for r in sessions:
        if isinstance(r, dict) and r.get("session_type") == "collaborative_reasoning" and r.get("external_id") == sessionId:
            sess = r
            break

    if sess is None:
        sess = {
            "id": _new_id("ct_sess"),
            "session_type": "collaborative_reasoning",
            "external_id": sessionId,
            "title": topic if isinstance(topic, str) else None,
            "iteration": iteration,
            "stage": stage,
            "status": "active",
            "next_action_needed": bool(nextContributionNeeded),
            "context_text": topic,
            "stakeholders": None,
            "constraints_text": None,
            "time_horizon": None,
            "risk_tolerance": None,
            "analysis_type": None,
            "overall_confidence": None,
            "uncertainty_areas": None,
            "recommended_approach": None,
            "diagram_type": None,
            "final_text": finalRecommendation if isinstance(finalRecommendation, str) else None,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)
    else:
        sess["iteration"] = iteration
        sess["stage"] = stage
        sess["next_action_needed"] = bool(nextContributionNeeded)
        sess["context_text"] = topic
        if sess.get("title") in (None, "") and isinstance(topic, str):
            sess["title"] = topic
        if isinstance(finalRecommendation, str):
            sess["final_text"] = finalRecommendation
        sess["updated_at"] = now

    # ---- Upsert personas by external_persona_id ----
    # Build index for this session
    sess_personas = [p for p in personas_rows if isinstance(p, dict) and p.get("session_id") == sess["id"]]
    idx = {p.get("external_persona_id"): p for p in sess_personas if isinstance(p.get("external_persona_id"), str)}

    for p in personas:
        ext_id = p["id"]
        row = idx.get(ext_id)
        if row is None:
            row = {
                "id": _new_id("ct_prs"),
                "session_id": sess["id"],
                "external_persona_id": ext_id,
                "name": p["name"],
                "expertise": p["expertise"],
                "background": p["background"],
                "perspective": p["perspective"],
                "biases": p["biases"],
                "communication_style": p["communication"]["style"],
                "communication_tone": p["communication"]["tone"],
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            personas_rows.append(row)
            idx[ext_id] = row
        else:
            # Update existing (do not enforce lifecycle transitions; tool doesn't request status changes)
            row["name"] = p["name"]
            row["expertise"] = p["expertise"]
            row["background"] = p["background"]
            row["perspective"] = p["perspective"]
            row["biases"] = p["biases"]
            row["communication_style"] = p["communication"]["style"]
            row["communication_tone"] = p["communication"]["tone"]
            if row.get("status") not in ("active", "inactive"):
                row["status"] = "active"
            row["updated_at"] = now

    # ---- Enforce that contribution personaId / activePersonaId / nextPersonaId reference defined personas ----
    valid_persona_ids = {p.get("external_persona_id") for p in personas_rows if isinstance(p, dict) and p.get("session_id") == sess["id"]}
    if activePersonaId not in valid_persona_ids:
        e = _err("VALIDATION_ERROR", "activePersonaId must reference a defined persona in this session.")
        _log("error", e["error"])
        return e
    if nextPersonaId is not None and nextPersonaId not in valid_persona_ids:
        e = _err("VALIDATION_ERROR", "nextPersonaId must reference a defined persona in this session when provided.")
        _log("error", e["error"])
        return e
    for i, c in enumerate(contributions):
        if c["personaId"] not in valid_persona_ids:
            e = _err("VALIDATION_ERROR", f"contributions[{i}].personaId must reference a defined persona in this session.")
            _log("error", e["error"])
            return e
    if disagreements is not None:
        for di, d in enumerate(disagreements):
            for pi, pos in enumerate(d["positions"]):
                if pos["personaId"] not in valid_persona_ids:
                    e = _err("VALIDATION_ERROR", f"disagreements[{di}].positions[{pi}].personaId must reference a defined persona in this session.")
                    _log("error", e["error"])
                    return e

    # ---- Append a session_event (normalized) ----
    seq = 0
    for ev in events:
        if isinstance(ev, dict) and ev.get("session_id") == sess["id"]:
            sn = ev.get("sequence_number")
            if isinstance(sn, int) and sn > seq:
                seq = sn
    seq += 1

    payload = {
        "topic": topic,
        "personas": personas,
        "contributions": contributions,
        "stage": stage,
        "activePersonaId": activePersonaId,
        "sessionId": sessionId,
        "iteration": iteration,
        "nextContributionNeeded": nextContributionNeeded,
    }
    if nextPersonaId is not None:
        payload["nextPersonaId"] = nextPersonaId
    if consensusPoints is not None:
        payload["consensusPoints"] = consensusPoints
    if disagreements is not None:
        payload["disagreements"] = disagreements
    if keyInsights is not None:
        payload["keyInsights"] = keyInsights
    if openQuestions is not None:
        payload["openQuestions"] = openQuestions
    if finalRecommendation is not None:
        payload["finalRecommendation"] = finalRecommendation
    if suggestedContributionTypes is not None:
        payload["suggestedContributionTypes"] = suggestedContributionTypes

    evt = {
        "id": _new_id("ct_evt"),
        "session_id": sess["id"],
        "tool_name": "collaborativereasoning",
        "event_type": "contribution",
        "sequence_number": seq,
        "iteration": iteration,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    events.append(evt)

    # Persist
    _save("reasoning_sessions.json", sessions)
    _save("collaboration_personas.json", personas_rows)
    _save("session_events.json", events)

    # Response: updated collaboration session state
    resp = {
        "session": sess,
        "personas": [p for p in personas_rows if isinstance(p, dict) and p.get("session_id") == sess["id"]],
        "latest_event": evt,
    }
    _log("ok", extra={"session_id": sess["id"]})
    return resp

def metacognitivemonitoring(task, stage, overallConfidence, uncertaintyAreas, recommendedApproach, monitoringId, iteration, nextAssessmentNeeded, knowledgeAssessment=None, claims=None, reasoningSteps=None, suggestedAssessments=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, tool_name="metacognitivemonitoring", extra=None):
        extra = extra or {}
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool": tool_name,
            "status": status,
            "timestamp": now,
            "latency_ms": int((time.time() - start) * 1000),
            **extra,
        }
        fn = "request_logs.json"
        data = _load(fn)
        if not isinstance(data, list):
            data = []
        data.append(row)
        _save(fn, data)

    def _enforce_limits():
        limits = _load("service_limits.json")
        if not limits or not isinstance(limits, dict):
            return None
        rlm = limits.get("rate_limit_per_minute")
        qpd = limits.get("quota_per_day")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        def _parse(ts):
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow().replace(microsecond=0)
        if isinstance(rlm, int) and rlm >= 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse(r.get("timestamp", ""))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= rlm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(qpd, int) and qpd >= 0:
            cutoff = now_dt - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                ts = _parse(r.get("timestamp", ""))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", extra={"error_code": lim_err["error"]["code"]})
        return lim_err

    # Validate required fields
    if not isinstance(task, str) or not task.strip():
        e = _err("VALIDATION_ERROR", "task must be a non-empty string", field="task")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    allowed_stage = {"knowledge-assessment", "planning", "execution", "monitoring", "evaluation", "reflection"}
    if not isinstance(stage, str) or stage not in allowed_stage:
        e = _err("VALIDATION_ERROR", "Invalid stage", field="stage", allowed=sorted(list(allowed_stage)))
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if not isinstance(overallConfidence, (int, float)) or overallConfidence < 0 or overallConfidence > 1:
        e = _err("VALIDATION_ERROR", "overallConfidence must be within [0,1]", field="overallConfidence")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if not isinstance(recommendedApproach, str) or not recommendedApproach.strip():
        e = _err("VALIDATION_ERROR", "recommendedApproach must be a non-empty string", field="recommendedApproach")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if not isinstance(monitoringId, str) or not monitoringId.strip():
        e = _err("VALIDATION_ERROR", "monitoringId must be a non-empty string", field="monitoringId")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if not (isinstance(iteration, int) or isinstance(iteration, float)) or int(iteration) != iteration or iteration < 0:
        e = _err("VALIDATION_ERROR", "iteration must be an integer >= 0", field="iteration")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    iteration = int(iteration)
    if not isinstance(nextAssessmentNeeded, bool):
        e = _err("VALIDATION_ERROR", "nextAssessmentNeeded must be boolean", field="nextAssessmentNeeded")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    if not isinstance(uncertaintyAreas, list) or any(not isinstance(x, str) for x in uncertaintyAreas):
        e = _err("VALIDATION_ERROR", "uncertaintyAreas must be an array of strings", field="uncertaintyAreas")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    # Business rule: non-empty array when nextAssessmentNeeded=true
    if nextAssessmentNeeded and len(uncertaintyAreas) == 0:
        e = _err("VALIDATION_ERROR", "uncertaintyAreas must be non-empty when nextAssessmentNeeded=true", field="uncertaintyAreas")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    # Validate nested confidence metrics in payload within [0,1]
    if knowledgeAssessment is not None:
        if not isinstance(knowledgeAssessment, dict):
            e = _err("VALIDATION_ERROR", "knowledgeAssessment must be an object", field="knowledgeAssessment")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        for req in ("domain", "knowledgeLevel", "confidenceScore", "supportingEvidence", "knownLimitations"):
            if req not in knowledgeAssessment:
                e = _err("VALIDATION_ERROR", f"Missing required knowledgeAssessment field: {req}", field=f"knowledgeAssessment.{req}")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e
        allowed_kl = {"expert", "proficient", "familiar", "basic", "minimal", "none"}
        if not isinstance(knowledgeAssessment["knowledgeLevel"], str) or knowledgeAssessment["knowledgeLevel"] not in allowed_kl:
            e = _err("VALIDATION_ERROR", "Invalid knowledgeLevel", field="knowledgeAssessment.knowledgeLevel", allowed=sorted(list(allowed_kl)))
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        cs = knowledgeAssessment["confidenceScore"]
        if not isinstance(cs, (int, float)) or cs < 0 or cs > 1:
            e = _err("VALIDATION_ERROR", "knowledgeAssessment.confidenceScore must be within [0,1]", field="knowledgeAssessment.confidenceScore")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        if not isinstance(knowledgeAssessment["knownLimitations"], list) or any(not isinstance(x, str) for x in knowledgeAssessment["knownLimitations"]):
            e = _err("VALIDATION_ERROR", "knownLimitations must be an array of strings", field="knowledgeAssessment.knownLimitations")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e

    if claims is not None:
        if not isinstance(claims, list):
            e = _err("VALIDATION_ERROR", "claims must be an array", field="claims")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        allowed_status = {"fact", "inference", "speculation", "uncertain"}
        for i, c in enumerate(claims):
            if not isinstance(c, dict):
                e = _err("VALIDATION_ERROR", "Each claim must be an object", field=f"claims[{i}]")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e
            for req in ("claim", "status", "confidenceScore", "evidenceBasis"):
                if req not in c:
                    e = _err("VALIDATION_ERROR", f"Missing required claim field: {req}", field=f"claims[{i}].{req}")
                    _log("error", extra={"error_code": e["error"]["code"]})
                    return e
            if not isinstance(c["status"], str) or c["status"] not in allowed_status:
                e = _err("VALIDATION_ERROR", "Invalid claims[].status", field=f"claims[{i}].status", allowed=sorted(list(allowed_status)))
                _log("error", extra={"error_code": e["error"]["code"]})
                return e
            cs = c["confidenceScore"]
            if not isinstance(cs, (int, float)) or cs < 0 or cs > 1:
                e = _err("VALIDATION_ERROR", "claims[].confidenceScore must be within [0,1]", field=f"claims[{i}].confidenceScore")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e

    if reasoningSteps is not None:
        if not isinstance(reasoningSteps, list):
            e = _err("VALIDATION_ERROR", "reasoningSteps must be an array", field="reasoningSteps")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        for i, s in enumerate(reasoningSteps):
            if not isinstance(s, dict):
                e = _err("VALIDATION_ERROR", "Each reasoningStep must be an object", field=f"reasoningSteps[{i}]")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e
            for req in ("step", "potentialBiases", "assumptions", "logicalValidity", "inferenceStrength"):
                if req not in s:
                    e = _err("VALIDATION_ERROR", f"Missing required reasoningStep field: {req}", field=f"reasoningSteps[{i}].{req}")
                    _log("error", extra={"error_code": e["error"]["code"]})
                    return e
            lv = s["logicalValidity"]
            is_ = s["inferenceStrength"]
            if not isinstance(lv, (int, float)) or lv < 0 or lv > 1:
                e = _err("VALIDATION_ERROR", "logicalValidity must be within [0,1]", field=f"reasoningSteps[{i}].logicalValidity")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e
            if not isinstance(is_, (int, float)) or is_ < 0 or is_ > 1:
                e = _err("VALIDATION_ERROR", "inferenceStrength must be within [0,1]", field=f"reasoningSteps[{i}].inferenceStrength")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e
            if not isinstance(s["potentialBiases"], list) or any(not isinstance(x, str) for x in s["potentialBiases"]):
                e = _err("VALIDATION_ERROR", "potentialBiases must be array of strings", field=f"reasoningSteps[{i}].potentialBiases")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e
            if not isinstance(s["assumptions"], list) or any(not isinstance(x, str) for x in s["assumptions"]):
                e = _err("VALIDATION_ERROR", "assumptions must be array of strings", field=f"reasoningSteps[{i}].assumptions")
                _log("error", extra={"error_code": e["error"]["code"]})
                return e

    if suggestedAssessments is not None:
        allowed_sa = {"knowledge", "claim", "reasoning", "overall"}
        if not isinstance(suggestedAssessments, list) or any((not isinstance(x, str) or x not in allowed_sa) for x in suggestedAssessments):
            e = _err("VALIDATION_ERROR", "suggestedAssessments must be an array of allowed values", field="suggestedAssessments", allowed=sorted(list(allowed_sa)))
            _log("error", extra={"error_code": e["error"]["code"]})
            return e

    # Upsert reasoning_sessions by (session_type, external_id)
    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    session_type = "metacognitive_monitoring"
    session = None
    for s in sessions:
        if s.get("session_type") == session_type and s.get("external_id") == monitoringId:
            session = s
            break

    if session is None:
        session = {
            "id": "rs_" + uuid.uuid4().hex,
            "session_type": session_type,
            "external_id": monitoringId,
            "title": task.strip()[:120],
            "iteration": iteration,
            "stage": stage,
            "status": "active",
            "next_action_needed": bool(nextAssessmentNeeded),
            "context_text": task,
            "stakeholders": None,
            "constraints_text": None,
            "time_horizon": None,
            "risk_tolerance": None,
            "analysis_type": None,
            "overall_confidence": float(overallConfidence),
            "uncertainty_areas": uncertaintyAreas,
            "recommended_approach": recommendedApproach,
            "diagram_type": None,
            "final_text": None,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(session)
    else:
        # Reject "backdate": iteration must not decrease
        prev_it = session.get("iteration")
        if isinstance(prev_it, int) and iteration < prev_it:
            e = _err("INVALID_TRANSITION", "Cannot decrease iteration (backdate) for monitoring session", previous_iteration=prev_it, attempted_iteration=iteration)
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        session["iteration"] = iteration
        session["stage"] = stage
        session["next_action_needed"] = bool(nextAssessmentNeeded)
        session["context_text"] = task
        session["overall_confidence"] = float(overallConfidence)
        session["uncertainty_areas"] = uncertaintyAreas
        session["recommended_approach"] = recommendedApproach
        session["updated_at"] = now
        if not session.get("title") and task.strip():
            session["title"] = task.strip()[:120]

    # Append event
    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []

    max_seq = 0
    for ev in events:
        if ev.get("session_id") == session["id"]:
            sn = ev.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn

    payload = {
        "task": task,
        "stage": stage,
        "knowledgeAssessment": knowledgeAssessment,
        "claims": claims,
        "reasoningSteps": reasoningSteps,
        "overallConfidence": float(overallConfidence),
        "uncertaintyAreas": uncertaintyAreas,
        "recommendedApproach": recommendedApproach,
        "monitoringId": monitoringId,
        "iteration": iteration,
        "suggestedAssessments": suggestedAssessments,
        "nextAssessmentNeeded": nextAssessmentNeeded,
    }

    ev_row = {
        "id": "ev_" + uuid.uuid4().hex,
        "session_id": session["id"],
        "tool_name": "metacognitivemonitoring",
        "event_type": "monitoring_update",
        "sequence_number": max_seq + 1,
        "iteration": iteration,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev_row)

    _save("reasoning_sessions.json", sessions)
    _save("session_events.json", events)

    body = {"session": session, "latest_event": ev_row, "state": payload}
    _log("ok")
    return body

def scientificmethod(stage, observation=None, question=None, hypothesis=None, experiment=None, analysis=None, conclusion=None, inquiryId=None, iteration=None, nextStageNeeded=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---------- audit / usage (best-effort; schema not provided) ----------
    def _log(endpoint, status, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_log.json", "request_logs.json", "usage.json", "audit_log.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            rows = _load(fname)
            if not isinstance(rows, list):
                rows = []
            rows.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": now
            })
            _save(fname, rows)
            break

    # ---------- validations ----------
    allowed_stage = {"observation", "question", "hypothesis", "experiment", "analysis", "conclusion", "iteration"}
    if stage not in allowed_stage:
        _log("scientificmethod", "error", "invalid stage")
        return _err("VALIDATION_ERROR", "Invalid stage.", field="stage")

    if not isinstance(inquiryId, str) or not inquiryId.strip():
        _log("scientificmethod", "error", "invalid inquiryId")
        return _err("VALIDATION_ERROR", "inquiryId must be a non-empty string.", field="inquiryId")

    if not (isinstance(iteration, int) or isinstance(iteration, float)) or iteration < 0 or int(iteration) != iteration:
        _log("scientificmethod", "error", "invalid iteration")
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0.", field="iteration")
    iteration = int(iteration)

    if not isinstance(nextStageNeeded, bool):
        _log("scientificmethod", "error", "invalid nextStageNeeded")
        return _err("VALIDATION_ERROR", "nextStageNeeded must be boolean.", field="nextStageNeeded")

    for sfield, sval in (("observation", observation), ("question", question), ("analysis", analysis), ("conclusion", conclusion)):
        if sval is not None and not isinstance(sval, str):
            _log("scientificmethod", "error", f"invalid {sfield}")
            return _err("VALIDATION_ERROR", f"{sfield} must be a string.", field=sfield)

    # Validate hypothesis object if provided
    if hypothesis is not None:
        if not isinstance(hypothesis, dict):
            _log("scientificmethod", "error", "hypothesis not object")
            return _err("VALIDATION_ERROR", "hypothesis must be an object.", field="hypothesis")
        req = ["statement", "variables", "assumptions", "hypothesisId", "confidence", "domain", "iteration", "status"]
        missing = [k for k in req if k not in hypothesis]
        if missing:
            _log("scientificmethod", "error", "hypothesis missing fields")
            return _err("VALIDATION_ERROR", "hypothesis missing required fields.", missing=missing, field="hypothesis")
        if not isinstance(hypothesis["statement"], str) or not hypothesis["statement"].strip():
            _log("scientificmethod", "error", "bad hypothesis.statement")
            return _err("VALIDATION_ERROR", "hypothesis.statement must be a non-empty string.", field="hypothesis.statement")
        if not isinstance(hypothesis["hypothesisId"], str) or not hypothesis["hypothesisId"].strip():
            _log("scientificmethod", "error", "bad hypothesis.hypothesisId")
            return _err("VALIDATION_ERROR", "hypothesis.hypothesisId must be a non-empty string.", field="hypothesis.hypothesisId")
        if not isinstance(hypothesis["domain"], str) or not hypothesis["domain"].strip():
            _log("scientificmethod", "error", "bad hypothesis.domain")
            return _err("VALIDATION_ERROR", "hypothesis.domain must be a non-empty string.", field="hypothesis.domain")
        conf = hypothesis["confidence"]
        if not isinstance(conf, (int, float)) or conf < 0 or conf > 1:
            _log("scientificmethod", "error", "bad hypothesis.confidence")
            return _err("VALIDATION_ERROR", "hypothesis.confidence must be within [0,1].", field="hypothesis.confidence")
        it = hypothesis["iteration"]
        if not isinstance(it, (int, float)) or it < 0 or int(it) != it:
            _log("scientificmethod", "error", "bad hypothesis.iteration")
            return _err("VALIDATION_ERROR", "hypothesis.iteration must be an integer >= 0.", field="hypothesis.iteration")
        if not isinstance(hypothesis["assumptions"], list) or len(hypothesis["assumptions"]) == 0 or any(not isinstance(x, str) for x in hypothesis["assumptions"]):
            _log("scientificmethod", "error", "bad hypothesis.assumptions")
            return _err("VALIDATION_ERROR", "hypothesis.assumptions must be a non-empty array of strings.", field="hypothesis.assumptions")
        if not isinstance(hypothesis["variables"], list) or len(hypothesis["variables"]) == 0:
            _log("scientificmethod", "error", "bad hypothesis.variables")
            return _err("VALIDATION_ERROR", "hypothesis.variables must be a non-empty array.", field="hypothesis.variables")
        allowed_vt = {"independent", "dependent", "controlled", "confounding"}
        for i, v in enumerate(hypothesis["variables"]):
            if not isinstance(v, dict):
                _log("scientificmethod", "error", "bad variable")
                return _err("VALIDATION_ERROR", "Each variable must be an object.", field=f"hypothesis.variables[{i}]")
            if "name" not in v or "type" not in v:
                _log("scientificmethod", "error", "variable missing required")
                return _err("VALIDATION_ERROR", "Each variable must include name and type.", field=f"hypothesis.variables[{i}]")
            if not isinstance(v["name"], str) or not v["name"].strip():
                _log("scientificmethod", "error", "bad variable.name")
                return _err("VALIDATION_ERROR", "Variable name must be a non-empty string.", field=f"hypothesis.variables[{i}].name")
            if v["type"] not in allowed_vt:
                _log("scientificmethod", "error", "bad variable.type")
                return _err("VALIDATION_ERROR", "Variable type invalid.", field=f"hypothesis.variables[{i}].type")
            if "operationalization" in v and v["operationalization"] is not None and not isinstance(v["operationalization"], str):
                _log("scientificmethod", "error", "bad operationalization")
                return _err("VALIDATION_ERROR", "operationalization must be a string.", field=f"hypothesis.variables[{i}].operationalization")
        allowed_hs = {"proposed", "testing", "supported", "refuted", "refined"}
        if hypothesis["status"] not in allowed_hs:
            _log("scientificmethod", "error", "bad hypothesis.status")
            return _err("VALIDATION_ERROR", "hypothesis.status invalid.", field="hypothesis.status")
        if "alternativeTo" in hypothesis and hypothesis["alternativeTo"] is not None:
            if not isinstance(hypothesis["alternativeTo"], list) or any(not isinstance(x, str) for x in hypothesis["alternativeTo"]):
                _log("scientificmethod", "error", "bad alternativeTo")
                return _err("VALIDATION_ERROR", "hypothesis.alternativeTo must be an array of strings.", field="hypothesis.alternativeTo")
        if "refinementOf" in hypothesis and hypothesis["refinementOf"] is not None and not isinstance(hypothesis["refinementOf"], str):
            _log("scientificmethod", "error", "bad refinementOf")
            return _err("VALIDATION_ERROR", "hypothesis.refinementOf must be a string.", field="hypothesis.refinementOf")

    # Validate experiment object if provided
    if experiment is not None:
        if not isinstance(experiment, dict):
            _log("scientificmethod", "error", "experiment not object")
            return _err("VALIDATION_ERROR", "experiment must be an object.", field="experiment")
        req = ["design", "methodology", "predictions", "experimentId", "hypothesisId", "controlMeasures"]
        missing = [k for k in req if k not in experiment]
        if missing:
            _log("scientificmethod", "error", "experiment missing fields")
            return _err("VALIDATION_ERROR", "experiment missing required fields.", missing=missing, field="experiment")
        for k in ("design", "methodology", "experimentId", "hypothesisId"):
            if not isinstance(experiment[k], str) or not experiment[k].strip():
                _log("scientificmethod", "error", f"bad experiment.{k}")
                return _err("VALIDATION_ERROR", f"experiment.{k} must be a non-empty string.", field=f"experiment.{k}")
        if not isinstance(experiment["controlMeasures"], list) or any(not isinstance(x, str) for x in experiment["controlMeasures"]):
            _log("scientificmethod", "error", "bad controlMeasures")
            return _err("VALIDATION_ERROR", "experiment.controlMeasures must be an array of strings.", field="experiment.controlMeasures")
        if not isinstance(experiment["predictions"], list):
            _log("scientificmethod", "error", "bad predictions")
            return _err("VALIDATION_ERROR", "experiment.predictions must be an array.", field="experiment.predictions")
        for i, p in enumerate(experiment["predictions"]):
            if not isinstance(p, dict):
                _log("scientificmethod", "error", "bad prediction")
                return _err("VALIDATION_ERROR", "Each prediction must be an object.", field=f"experiment.predictions[{i}]")
            if "if" not in p or "then" not in p:
                _log("scientificmethod", "error", "prediction missing required")
                return _err("VALIDATION_ERROR", "Each prediction must include if and then.", field=f"experiment.predictions[{i}]")
            if not isinstance(p["if"], str) or not p["if"].strip():
                _log("scientificmethod", "error", "bad prediction.if")
                return _err("VALIDATION_ERROR", "prediction.if must be a non-empty string.", field=f"experiment.predictions[{i}].if")
            if not isinstance(p["then"], str) or not p["then"].strip():
                _log("scientificmethod", "error", "bad prediction.then")
                return _err("VALIDATION_ERROR", "prediction.then must be a non-empty string.", field=f"experiment.predictions[{i}].then")
            if "else" in p and p["else"] is not None and not isinstance(p["else"], str):
                _log("scientificmethod", "error", "bad prediction.else")
                return _err("VALIDATION_ERROR", "prediction.else must be a string.", field=f"experiment.predictions[{i}].else")
        for k in ("results", "unexpectedObservations", "limitations", "nextSteps", "outcomeMatched"):
            if k in experiment and experiment[k] is not None:
                if k == "outcomeMatched":
                    if not isinstance(experiment[k], bool):
                        _log("scientificmethod", "error", "bad outcomeMatched")
                        return _err("VALIDATION_ERROR", "experiment.outcomeMatched must be boolean.", field="experiment.outcomeMatched")
                elif k in ("unexpectedObservations", "limitations", "nextSteps"):
                    if not isinstance(experiment[k], list) or any(not isinstance(x, str) for x in experiment[k]):
                        _log("scientificmethod", "error", f"bad {k}")
                        return _err("VALIDATION_ERROR", f"experiment.{k} must be an array of strings.", field=f"experiment.{k}")
                else:
                    if not isinstance(experiment[k], str):
                        _log("scientificmethod", "error", "bad results")
                        return _err("VALIDATION_ERROR", "experiment.results must be a string.", field="experiment.results")

    # ---------- upsert reasoning session ----------
    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    session_type = "scientific_method"
    sess = None
    for r in sessions:
        if isinstance(r, dict) and r.get("session_type") == session_type and r.get("external_id") == inquiryId:
            sess = r
            break

    if sess is None:
        sess = {
            "id": "rs_" + uuid.uuid4().hex,
            "session_type": session_type,
            "external_id": inquiryId,
            "title": None,
            "iteration": iteration,
            "stage": stage,
            "status": "active",
            "next_action_needed": bool(nextStageNeeded),
            "context_text": question or observation or None,
            "stakeholders": None,
            "constraints_text": None,
            "time_horizon": None,
            "risk_tolerance": None,
            "analysis_type": None,
            "overall_confidence": None,
            "uncertainty_areas": None,
            "recommended_approach": None,
            "diagram_type": None,
            "final_text": None,
            "created_at": now,
            "updated_at": now
        }
        sessions.append(sess)
    else:
        sess["iteration"] = iteration
        sess["stage"] = stage
        sess["next_action_needed"] = bool(nextStageNeeded)
        if sess.get("context_text") is None and (question or observation):
            sess["context_text"] = question or observation
        sess["updated_at"] = now

    # ---------- persist scientific artifacts (upsert) ----------
    artifacts = _load("scientific_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    def _find_artifact(session_id, artifact_type, external_artifact_id):
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("session_id") == session_id and a.get("artifact_type") == artifact_type and a.get("external_artifact_id") == external_artifact_id:
                return a
        return None

    def _new_artifact_base(session_id, artifact_type, external_artifact_id, parent_external_id):
        return {
            "id": "sa_" + uuid.uuid4().hex,
            "session_id": session_id,
            "artifact_type": artifact_type,
            "external_artifact_id": external_artifact_id,
            "parent_external_id": parent_external_id,
            "statement": None,
            "domain": None,
            "confidence": None,
            "hypothesis_status": None,
            "assumptions": None,
            "alternative_to": None,
            "refinement_of": None,
            "variable_name": None,
            "variable_type": None,
            "operationalization": None,
            "experiment_design": None,
            "methodology": None,
            "control_measures": None,
            "results": None,
            "outcome_matched": None,
            "unexpected_observations": None,
            "limitations": None,
            "next_steps": None,
            "prediction_if": None,
            "prediction_then": None,
            "prediction_else": None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }

    # hypothesis lifecycle transitions
    allowed_hyp_transitions = {
        "proposed": {"testing"},
        "testing": {"supported", "refuted", "refined"},
        "supported": set(),
        "refuted": set(),
        "refined": {"testing"}
    }

    if hypothesis is not None:
        hid = hypothesis["hypothesisId"]
        existing = _find_artifact(sess["id"], "hypothesis", hid)
        new_status = hypothesis["status"]

        if existing is None:
            # Must satisfy constraints for hypothesis artifact
            existing = _new_artifact_base(sess["id"], "hypothesis", hid, None)
            existing["statement"] = hypothesis["statement"]
            existing["domain"] = hypothesis["domain"]
            existing["confidence"] = float(hypothesis["confidence"])
            existing["hypothesis_status"] = new_status
            existing["assumptions"] = list(hypothesis["assumptions"])
            existing["alternative_to"] = list(hypothesis.get("alternativeTo") or []) if hypothesis.get("alternativeTo") is not None else None
            existing["refinement_of"] = hypothesis.get("refinementOf")
            artifacts.append(existing)
        else:
            prior = existing.get("hypothesis_status")
            if prior is not None and new_status != prior:
                if new_status not in allowed_hyp_transitions.get(prior, set()):
                    _log("scientificmethod", "error", "invalid hypothesis status transition")
                    return _err("INVALID_TRANSITION", "Illegal hypothesis.status transition.", from_status=prior, to_status=new_status)
            existing["statement"] = hypothesis["statement"]
            existing["domain"] = hypothesis["domain"]
            existing["confidence"] = float(hypothesis["confidence"])
            existing["hypothesis_status"] = new_status
            existing["assumptions"] = list(hypothesis["assumptions"])
            existing["alternative_to"] = list(hypothesis.get("alternativeTo") or []) if hypothesis.get("alternativeTo") is not None else None
            existing["refinement_of"] = hypothesis.get("refinementOf")
            existing["updated_at"] = now

        # variables: one row per variable (derive external id deterministically)
        for v in hypothesis["variables"]:
            v_ext = f"{hid}:var:{v['name']}"
            vrow = _find_artifact(sess["id"], "variable", v_ext)
            if vrow is None:
                vrow = _new_artifact_base(sess["id"], "variable", v_ext, hid)
                artifacts.append(vrow)
            vrow["parent_external_id"] = hid
            vrow["variable_name"] = v["name"]
            vrow["variable_type"] = v["type"]
            vrow["operationalization"] = v.get("operationalization")
            vrow["status"] = "active"
            if "created_at" not in vrow or vrow.get("created_at") is None:
                vrow["created_at"] = now
            vrow["updated_at"] = now

    if experiment is not None:
        # Ensure hypothesis artifact exists when experiment references it
        exp_hid = experiment["hypothesisId"]
        if _find_artifact(sess["id"], "hypothesis", exp_hid) is None and (hypothesis is None or hypothesis.get("hypothesisId") != exp_hid):
            _log("scientificmethod", "error", "experiment references missing hypothesis")
            return _err("NOT_FOUND", "experiment.hypothesisId does not refer to a persisted hypothesis in this inquiry.", field="experiment.hypothesisId")

        eid = experiment["experimentId"]
        exrow = _find_artifact(sess["id"], "experiment", eid)
        if exrow is None:
            exrow = _new_artifact_base(sess["id"], "experiment", eid, exp_hid)
            artifacts.append(exrow)
        exrow["parent_external_id"] = exp_hid
        exrow["experiment_design"] = experiment["design"]
        exrow["methodology"] = experiment["methodology"]
        exrow["control_measures"] = list(experiment["controlMeasures"])
        exrow["results"] = experiment.get("results")
        exrow["outcome_matched"] = experiment.get("outcomeMatched")
        exrow["unexpected_observations"] = list(experiment.get("unexpectedObservations") or []) if experiment.get("unexpectedObservations") is not None else None
        exrow["limitations"] = list(experiment.get("limitations") or []) if experiment.get("limitations") is not None else None
        exrow["next_steps"] = list(experiment.get("nextSteps") or []) if experiment.get("nextSteps") is not None else None
        exrow["status"] = "active"
        if "created_at" not in exrow or exrow.get("created_at") is None:
            exrow["created_at"] = now
        exrow["updated_at"] = now

        # predictions: one row per prediction (derive external id deterministically by index+hash)
        preds = experiment["predictions"]
        for idx, p in enumerate(preds, start=1):
            p_key = f"{eid}:pred:{idx}:{abs(hash((p.get('if'), p.get('then'), p.get('else')))) % (10**10)}"
            prow = _find_artifact(sess["id"], "prediction", p_key)
            if prow is None:
                prow = _new_artifact_base(sess["id"], "prediction", p_key, eid)
                artifacts.append(prow)
            prow["parent_external_id"] = eid
            prow["prediction_if"] = p["if"]
            prow["prediction_then"] = p["then"]
            prow["prediction_else"] = p.get("else")
            prow["status"] = "active"
            if "created_at" not in prow or prow.get("created_at") is None:
                prow["created_at"] = now
            prow["updated_at"] = now

    # ---------- append session event ----------
    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []

    max_seq = 0
    for e in events:
        if isinstance(e, dict) and e.get("session_id") == sess["id"]:
            sn = e.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn

    payload = {
        "stage": stage,
        "observation": observation,
        "question": question,
        "hypothesis": hypothesis,
        "experiment": experiment,
        "analysis": analysis,
        "conclusion": conclusion,
        "inquiryId": inquiryId,
        "iteration": iteration,
        "nextStageNeeded": nextStageNeeded
    }

    ev = {
        "id": "se_" + uuid.uuid4().hex,
        "session_id": sess["id"],
        "tool_name": "scientificmethod",
        "event_type": "scientific_update",
        "sequence_number": max_seq + 1,
        "iteration": iteration,
        "payload": payload,
        "created_at": now,
        "updated_at": now
    }
    events.append(ev)

    _save("reasoning_sessions.json", sessions)
    _save("scientific_artifacts.json", artifacts)
    _save("session_events.json", events)

    _log("scientificmethod", "ok")

    return {
        "session": sess,
        "event": ev,
        "artifacts_written": True
    }

def structuredargumentation(claim, premises, conclusion, argumentType, confidence, nextArgumentNeeded, argumentId=None, respondsTo=None, supports=None, contradicts=None, strengths=None, weaknesses=None, suggestedNextTypes=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_log.json", "request_logs.json", "usage.json", "audit_log.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            rows = _load(fname)
            if not isinstance(rows, list):
                rows = []
            rows.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": now
            })
            _save(fname, rows)
            break

    if not isinstance(claim, str) or not claim.strip():
        _log("structuredargumentation", "error", "bad claim")
        return _err("VALIDATION_ERROR", "claim must be a non-empty string.", field="claim")
    if not isinstance(conclusion, str) or not conclusion.strip():
        _log("structuredargumentation", "error", "bad conclusion")
        return _err("VALIDATION_ERROR", "conclusion must be a non-empty string.", field="conclusion")
    if not isinstance(premises, list) or any(not isinstance(x, str) for x in premises):
        _log("structuredargumentation", "error", "bad premises")
        return _err("VALIDATION_ERROR", "premises must be an array of strings.", field="premises")
    allowed_types = {"thesis", "antithesis", "synthesis", "objection", "rebuttal"}
    if argumentType not in allowed_types:
        _log("structuredargumentation", "error", "bad argumentType")
        return _err("VALIDATION_ERROR", "argumentType invalid.", field="argumentType")
    if not isinstance(confidence, (int, float)) or confidence < 0 or confidence > 1:
        _log("structuredargumentation", "error", "bad confidence")
        return _err("VALIDATION_ERROR", "confidence must be within [0,1].", field="confidence")
    if not isinstance(nextArgumentNeeded, bool):
        _log("structuredargumentation", "error", "bad nextArgumentNeeded")
        return _err("VALIDATION_ERROR", "nextArgumentNeeded must be boolean.", field="nextArgumentNeeded")

    for f, v in (("respondsTo", respondsTo), ("argumentId", argumentId)):
        if v is not None and (not isinstance(v, str) or not v.strip()):
            _log("structuredargumentation", "error", f"bad {f}")
            return _err("VALIDATION_ERROR", f"{f} must be a non-empty string when provided.", field=f)

    def _validate_str_list(field, v):
        if v is None:
            return None
        if not isinstance(v, list) or any(not isinstance(x, str) or not x.strip() for x in v):
            return _err("VALIDATION_ERROR", f"{field} must be an array of non-empty strings.", field=field)
        return None

    for field, v in (("supports", supports), ("contradicts", contradicts), ("strengths", strengths), ("weaknesses", weaknesses)):
        e = _validate_str_list(field, v)
        if e:
            _log("structuredargumentation", "error", f"bad {field}")
            return e

    if suggestedNextTypes is not None:
        if not isinstance(suggestedNextTypes, list) or any(x not in allowed_types for x in suggestedNextTypes):
            _log("structuredargumentation", "error", "bad suggestedNextTypes")
            return _err("VALIDATION_ERROR", "suggestedNextTypes must be an array of valid argument types.", field="suggestedNextTypes")

    # Upsert a session by external_id if provided in argumentId; otherwise create a session per run (auditability)
    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    session_type = "structured_argumentation"
    external_id = argumentId if argumentId is not None else ("argstream_" + uuid.uuid4().hex[:12])

    sess = None
    for r in sessions:
        if isinstance(r, dict) and r.get("session_type") == session_type and r.get("external_id") == external_id:
            sess = r
            break

    if sess is None:
        sess = {
            "id": "rs_" + uuid.uuid4().hex,
            "session_type": session_type,
            "external_id": external_id,
            "title": claim[:120] if isinstance(claim, str) else None,
            "iteration": 0,
            "stage": None,
            "status": "active",
            "next_action_needed": bool(nextArgumentNeeded),
            "context_text": claim,
            "stakeholders": None,
            "constraints_text": None,
            "time_horizon": None,
            "risk_tolerance": None,
            "analysis_type": None,
            "overall_confidence": None,
            "uncertainty_areas": None,
            "recommended_approach": None,
            "diagram_type": None,
            "final_text": None,
            "created_at": now,
            "updated_at": now
        }
        sessions.append(sess)
    else:
        sess["next_action_needed"] = bool(nextArgumentNeeded)
        sess["updated_at"] = now
        if sess.get("title") is None:
            sess["title"] = claim[:120]

    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []

    # Validate respondsTo exists earlier in the same session stream
    if respondsTo is not None:
        found = False
        for e in events:
            if not isinstance(e, dict) or e.get("session_id") != sess["id"]:
                continue
            if e.get("tool_name") == "structuredargumentation" and e.get("event_type") == "argument":
                pl = e.get("payload") or {}
                if isinstance(pl, dict) and pl.get("argumentId") == respondsTo:
                    found = True
                    break
        if not found:
            _log("structuredargumentation", "error", "respondsTo not found")
            return _err("NOT_FOUND", "respondsTo must refer to an existing earlier argumentId in this session.", field="respondsTo")

    max_seq = 0
    for e in events:
        if isinstance(e, dict) and e.get("session_id") == sess["id"]:
            sn = e.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn

    payload = {
        "claim": claim,
        "premises": premises,
        "conclusion": conclusion,
        "argumentType": argumentType,
        "confidence": float(confidence),
        "argumentId": argumentId,
        "respondsTo": respondsTo,
        "supports": supports,
        "contradicts": contradicts,
        "strengths": strengths,
        "weaknesses": weaknesses,
        "nextArgumentNeeded": nextArgumentNeeded,
        "suggestedNextTypes": suggestedNextTypes
    }

    ev = {
        "id": "se_" + uuid.uuid4().hex,
        "session_id": sess["id"],
        "tool_name": "structuredargumentation",
        "event_type": "argument",
        "sequence_number": max_seq + 1,
        "iteration": int(sess.get("iteration") or 0),
        "payload": payload,
        "created_at": now,
        "updated_at": now
    }
    events.append(ev)

    _save("reasoning_sessions.json", sessions)
    _save("session_events.json", events)
    _log("structuredargumentation", "ok")

    return {"session": sess, "event": ev}

def visualreasoning(operation, elements=None, transformationType=None, diagramId=None, diagramType=None, iteration=None, observation=None, insight=None, hypothesis=None, nextOperationNeeded=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_log.json", "request_logs.json", "usage.json", "audit_log.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            rows = _load(fname)
            if not isinstance(rows, list):
                rows = []
            rows.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": now
            })
            _save(fname, rows)
            break

    allowed_ops = {"create", "update", "delete", "transform", "observe"}
    if operation not in allowed_ops:
        _log("visualreasoning", "error", "bad operation")
        return _err("VALIDATION_ERROR", "operation invalid.", field="operation")
    if not isinstance(diagramId, str) or not diagramId.strip():
        _log("visualreasoning", "error", "bad diagramId")
        return _err("VALIDATION_ERROR", "diagramId must be a non-empty string.", field="diagramId")
    allowed_dt = {"graph", "flowchart", "stateDiagram", "conceptMap", "treeDiagram", "custom"}
    if diagramType not in allowed_dt:
        _log("visualreasoning", "error", "bad diagramType")
        return _err("VALIDATION_ERROR", "diagramType invalid.", field="diagramType")
    if not (isinstance(iteration, int) or isinstance(iteration, float)) or iteration < 0 or int(iteration) != iteration:
        _log("visualreasoning", "error", "bad iteration")
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0.", field="iteration")
    iteration = int(iteration)
    if not isinstance(nextOperationNeeded, bool):
        _log("visualreasoning", "error", "bad nextOperationNeeded")
        return _err("VALIDATION_ERROR", "nextOperationNeeded must be boolean.", field="nextOperationNeeded")

    for sfield, sval in (("observation", observation), ("insight", insight), ("hypothesis", hypothesis)):
        if sval is not None and not isinstance(sval, str):
            _log("visualreasoning", "error", f"bad {sfield}")
            return _err("VALIDATION_ERROR", f"{sfield} must be a string.", field=sfield)

    if transformationType is not None:
        allowed_tt = {"rotate", "move", "resize", "recolor", "regroup"}
        if transformationType not in allowed_tt:
            _log("visualreasoning", "error", "bad transformationType")
            return _err("VALIDATION_ERROR", "transformationType invalid.", field="transformationType")

    if elements is not None:
        if not isinstance(elements, list):
            _log("visualreasoning", "error", "elements not list")
            return _err("VALIDATION_ERROR", "elements must be an array.", field="elements")
        allowed_et = {"node", "edge", "container", "annotation"}
        for i, el in enumerate(elements):
            if not isinstance(el, dict):
                _log("visualreasoning", "error", "bad element")
                return _err("VALIDATION_ERROR", "Each element must be an object.", field=f"elements[{i}]")
            for req in ("id", "type", "properties"):
                if req not in el:
                    _log("visualreasoning", "error", "element missing required")
                    return _err("VALIDATION_ERROR", "Element missing required fields.", field=f"elements[{i}]", missing=[req])
            if not isinstance(el["id"], str) or not el["id"].strip():
                _log("visualreasoning", "error", "bad element.id")
                return _err("VALIDATION_ERROR", "Element id must be a non-empty string.", field=f"elements[{i}].id")
            if el["type"] not in allowed_et:
                _log("visualreasoning", "error", "bad element.type")
                return _err("VALIDATION_ERROR", "Element type invalid.", field=f"elements[{i}].type")
            if not isinstance(el["properties"], dict):
                _log("visualreasoning", "error", "bad element.properties")
                return _err("VALIDATION_ERROR", "Element properties must be an object.", field=f"elements[{i}].properties")
            if "label" in el and el["label"] is not None and not isinstance(el["label"], str):
                _log("visualreasoning", "error", "bad element.label")
                return _err("VALIDATION_ERROR", "Element label must be a string.", field=f"elements[{i}].label")
            if el["type"] == "edge":
                # edge must have source/target (further validated against current state below)
                if "source" not in el or "target" not in el:
                    _log("visualreasoning", "error", "edge missing source/target")
                    return _err("VALIDATION_ERROR", "Edge elements must include source and target.", field=f"elements[{i}]")
                if not isinstance(el["source"], str) or not el["source"].strip() or not isinstance(el["target"], str) or not el["target"].strip():
                    _log("visualreasoning", "error", "bad edge endpoints")
                    return _err("VALIDATION_ERROR", "Edge source/target must be non-empty strings.", field=f"elements[{i}]")
            if el["type"] == "container":
                if "contains" in el and el["contains"] is not None:
                    if not isinstance(el["contains"], list) or any(not isinstance(x, str) for x in el["contains"]):
                        _log("visualreasoning", "error", "bad contains")
                        return _err("VALIDATION_ERROR", "container.contains must be an array of strings.", field=f"elements[{i}].contains")

    # Upsert session
    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    session_type = "visual_reasoning"

    sess = None
    for r in sessions:
        if isinstance(r, dict) and r.get("session_type") == session_type and r.get("external_id") == diagramId:
            sess = r
            break
    if sess is None:
        sess = {
            "id": "rs_" + uuid.uuid4().hex,
            "session_type": session_type,
            "external_id": diagramId,
            "title": None,
            "iteration": iteration,
            "stage": None,
            "status": "active",
            "next_action_needed": bool(nextOperationNeeded),
            "context_text": None,
            "stakeholders": None,
            "constraints_text": None,
            "time_horizon": None,
            "risk_tolerance": None,
            "analysis_type": None,
            "overall_confidence": None,
            "uncertainty_areas": None,
            "recommended_approach": None,
            "diagram_type": diagramType,
            "final_text": None,
            "created_at": now,
            "updated_at": now
        }
        sessions.append(sess)
    else:
        sess["iteration"] = iteration
        sess["next_action_needed"] = bool(nextOperationNeeded)
        sess["diagram_type"] = diagramType
        sess["updated_at"] = now

    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []

    # Reconstruct current diagram state by replaying events for this session+diagramId
    state = {}  # id -> element dict
    for e in sorted([x for x in events if isinstance(x, dict) and x.get("session_id") == sess["id"] and x.get("tool_name") == "visualreasoning" and x.get("event_type") == "diagram_operation"], key=lambda r: r.get("sequence_number") or 0):
        pl = e.get("payload") or {}
        if not isinstance(pl, dict):
            continue
        if pl.get("diagramId") != diagramId:
            continue
        op = pl.get("operation")
        els = pl.get("elements") or []
        if not isinstance(els, list):
            continue
        if op in ("create", "update", "transform", "observe"):
            for el in els:
                if isinstance(el, dict) and "id" in el:
                    state[el["id"]] = el
        elif op == "delete":
            for el in els:
                if isinstance(el, dict) and "id" in el and el["id"] in state:
                    state.pop(el["id"], None)

    # Validate edge endpoints against current state (nodes only) BEFORE appending this event
    if elements is not None:
        node_ids = {eid for eid, el in state.items() if isinstance(el, dict) and el.get("type") == "node"}
        # If this operation also creates nodes in same request, include them for validation when op is create/update/transform
        if operation in ("create", "update", "transform"):
            for el in elements:
                if isinstance(el, dict) and el.get("type") == "node":
                    node_ids.add(el.get("id"))
        for el in elements:
            if isinstance(el, dict) and el.get("type") == "edge":
                if el.get("source") not in node_ids or el.get("target") not in node_ids:
                    _log("visualreasoning", "error", "edge endpoints missing")
                    return _err("VALIDATION_ERROR", "Edge source/target must refer to existing node ids in the current diagram state.", field="elements")

    # Append event
    max_seq = 0
    for e in events:
        if isinstance(e, dict) and e.get("session_id") == sess["id"]:
            sn = e.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn

    payload = {
        "operation": operation,
        "diagramId": diagramId,
        "diagramType": diagramType,
        "elements": elements,
        "transformationType": transformationType,
        "observation": observation,
        "insight": insight,
        "hypothesis": hypothesis,
        "iteration": iteration,
        "nextOperationNeeded": nextOperationNeeded
    }

    ev = {
        "id": "se_" + uuid.uuid4().hex,
        "session_id": sess["id"],
        "tool_name": "visualreasoning",
        "event_type": "diagram_operation",
        "sequence_number": max_seq + 1,
        "iteration": iteration,
        "payload": payload,
        "created_at": now,
        "updated_at": now
    }
    events.append(ev)

    _save("reasoning_sessions.json", sessions)
    _save("session_events.json", events)
    _log("visualreasoning", "ok")

    return {"session": sess, "event": ev}

def listsessions(credential, sessionType=None, externalId=None, status=None, stage=None, nextActionNeeded=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # usage log + simple rate limit if request log exists (60/min per credential)
    def _log(endpoint, status_s, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_log.json", "request_logs.json", "usage.json", "audit_log.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            rows = _load(fname)
            if not isinstance(rows, list):
                rows = []
            rows.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential": credential,
                "status": status_s,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": now
            })
            _save(fname, rows)
            break

    # authenticate credential if there is a credentials store; otherwise accept (ambient)
    authed = False
    for fname in ("credentials.json", "api_keys.json", "keys.json"):
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            continue
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            if credential == r.get("id") or credential == r.get("credential") or credential == r.get("key") or credential == r.get("token") or credential == r.get("value"):
                # accept any matching row
                authed = True
                break
        if rows and not authed:
            _log("listsessions", "error", "unauthorized")
            return _err("UNAUTHORIZED", "Invalid credential.")
        if rows and authed:
            break
    if not authed:
        authed = True  # ambient

    # rate limit if request log exists
    for fname in ("request_log.json", "request_logs.json"):
        path = os.path.join(_DB, fname)
        if os.path.exists(path):
            rows = _load(fname)
            if not isinstance(rows, list):
                rows = []
            # count last 60s
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in rows:
                if not isinstance(r, dict):
                    continue
                if r.get("credential") != credential:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= 60:
                _log("listsessions", "error", "rate_limit")
                return _err("RATE_LIMIT", "Too many requests.")
            break

    allowed_session_types = {
        "sequential_thinking", "collaborative_reasoning", "decision_framework",
        "metacognitive_monitoring", "scientific_method", "structured_argumentation", "visual_reasoning"
    }
    if sessionType is not None and sessionType not in allowed_session_types:
        _log("listsessions", "error", "bad sessionType")
        return _err("VALIDATION_ERROR", "sessionType invalid.", field="sessionType")
    if status is not None and status not in {"active", "paused", "completed", "archived"}:
        _log("listsessions", "error", "bad status")
        return _err("VALIDATION_ERROR", "status invalid.", field="status")
    if nextActionNeeded is not None and not isinstance(nextActionNeeded, bool):
        _log("listsessions", "error", "bad nextActionNeeded")
        return _err("VALIDATION_ERROR", "nextActionNeeded must be boolean.", field="nextActionNeeded")
    for f, v in (("externalId", externalId), ("stage", stage), ("cursor", cursor), ("sort", sort), ("order", order)):
        if v is not None and not isinstance(v, str):
            _log("listsessions", "error", f"bad {f}")
            return _err("VALIDATION_ERROR", f"{f} must be a string.", field=f)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("listsessions", "error", "bad limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if sort is None:
        sort = "updated_at"
    if sort not in {"created_at", "updated_at"}:
        _log("listsessions", "error", "bad sort")
        return _err("VALIDATION_ERROR", "sort invalid.", field="sort")
    if order is None:
        order = "desc"
    if order not in {"asc", "desc"}:
        _log("listsessions", "error", "bad order")
        return _err("VALIDATION_ERROR", "order invalid.", field="order")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    ca = _parse_rfc3339(createdAfter)
    if createdAfter is not None and ca is None:
        _log("listsessions", "error", "bad createdAfter")
        return _err("VALIDATION_ERROR", "createdAfter must be RFC3339 date-time.", field="createdAfter")
    cb = _parse_rfc3339(createdBefore)
    if createdBefore is not None and cb is None:
        _log("listsessions", "error", "bad createdBefore")
        return _err("VALIDATION_ERROR", "createdBefore must be RFC3339 date-time.", field="createdBefore")
    if ca and cb and ca > cb:
        _log("listsessions", "error", "createdAfter>createdBefore")
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore.")

    # decode cursor
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
        except Exception:
            _log("listsessions", "error", "bad cursor")
            return _err("VALIDATION_ERROR", "cursor is invalid/opaque.")

    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # filter
    out = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if sessionType is not None and s.get("session_type") != sessionType:
            continue
        if externalId is not None and s.get("external_id") != externalId:
            continue
        if status is not None and s.get("status") != status:
            continue
        if stage is not None and s.get("stage") != stage:
            continue
        if nextActionNeeded is not None and s.get("next_action_needed") != nextActionNeeded:
            continue
        if ca or cb:
            cts = s.get("created_at")
            if not isinstance(cts, str):
                continue
            try:
                cdt = datetime.datetime.fromisoformat(cts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if ca and cdt < ca:
                continue
            if cb and cdt > cb:
                continue
        out.append(s)

    def _ts(s, key):
        v = s.get(key)
        if not isinstance(v, str):
            return datetime.datetime(1970, 1, 1)
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return datetime.datetime(1970, 1, 1)

    reverse = (order == "desc")
    out.sort(key=lambda r: (_ts(r, sort), r.get("id") or ""), reverse=reverse)

    total = len(out)
    page = out[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_off}".encode("utf-8")).decode("utf-8")

    # summary shape
    items = []
    for s in page:
        items.append({
            "id": s.get("id"),
            "session_type": s.get("session_type"),
            "external_id": s.get("external_id"),
            "title": s.get("title"),
            "iteration": s.get("iteration"),
            "stage": s.get("stage"),
            "status": s.get("status"),
            "next_action_needed": s.get("next_action_needed"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at")
        })

    _log("listsessions", "ok")
    return {
        "data": items,
        "page": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def getsession(credential, sessionType, externalId, include=None, eventsLimit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts[:-1] if ts.endswith("Z") else ts
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    def _log(status, error=None, extra=None, cred_used=None):
        try:
            path = os.path.join(_DB, "request_logs.json")
            if not os.path.exists(path):
                return
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": _new_id("ct_req"),
                "endpoint": "getsession",
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if cred_used is not None:
                row["credential"] = cred_used
            if isinstance(extra, dict):
                row.update(extra)
            if isinstance(error, dict):
                row["error"] = error
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    def _enforce_limits(cred_used=None):
        try:
            limits_path = os.path.join(_DB, "service_limits.json")
            logs_path = os.path.join(_DB, "request_logs.json")
            if not (os.path.exists(limits_path) and os.path.exists(logs_path)):
                return None
            limits = _load("service_limits.json")
            if not isinstance(limits, dict):
                return None
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []

            rlm = limits.get("rate_limit_per_minute")
            qpd = limits.get("quota_per_day")

            if isinstance(rlm, int) and rlm >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if cred_used is not None and r.get("credential") not in (None, cred_used):
                        continue
                    dt = _parse_ts(r.get("timestamp"))
                    if dt and dt >= cutoff:
                        cnt += 1
                if cnt >= rlm:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")

            if isinstance(qpd, int) and qpd >= 0:
                day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if cred_used is not None and r.get("credential") not in (None, cred_used):
                        continue
                    dt = _parse_ts(r.get("timestamp"))
                    if dt and dt >= day_start:
                        cnt += 1
                if cnt >= qpd:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            return None
        except Exception:
            return None

    # ---- Validate inputs (relax credential: accept any string; auth is ambient unless explicit store exists) ----
    allowed_session_types = {
        "sequential_thinking",
        "collaborative_reasoning",
        "decision_framework",
        "metacognitive_monitoring",
        "scientific_method",
        "structured_argumentation",
        "visual_reasoning",
    }
    if not isinstance(credential, str) or not credential:
        e = _err("VALIDATION_ERROR", "credential must be a non-empty string.")
        _log("error", e["error"])
        return e
    if sessionType not in allowed_session_types:
        e = _err("VALIDATION_ERROR", "sessionType is invalid.", allowed=list(sorted(allowed_session_types)))
        _log("error", e["error"], cred_used=credential)
        return e
    if not isinstance(externalId, str) or not externalId:
        e = _err("VALIDATION_ERROR", "externalId must be a non-empty string.")
        _log("error", e["error"], cred_used=credential)
        return e
    if include is not None:
        allowed_include = {"latest_events", "personas", "decision_components", "scientific_artifacts"}
        if not isinstance(include, list) or any((not isinstance(x, str) or x not in allowed_include) for x in include):
            e = _err("VALIDATION_ERROR", "include is invalid.", allowed=list(sorted(allowed_include)))
            _log("error", e["error"], cred_used=credential)
            return e
    else:
        include = []
    if eventsLimit is None:
        eventsLimit = 100
    if not isinstance(eventsLimit, int) or eventsLimit < 1 or eventsLimit > 500:
        e = _err("VALIDATION_ERROR", "eventsLimit must be an integer within [1,500].")
        _log("error", e["error"], cred_used=credential)
        return e

    limit_err = _enforce_limits(cred_used=credential)
    if limit_err is not None:
        _log("error", limit_err["error"], cred_used=credential)
        return limit_err

    # ---- Authorization: only enforce if an auth store exists; otherwise ambient/allow ----
    # If service has credentials.json/access control, require match; else permit.
    try:
        cred_path = os.path.join(_DB, "credentials.json")
        if os.path.exists(cred_path):
            creds = _load("credentials.json")
            ok = False
            if isinstance(creds, list):
                for c in creds:
                    if not isinstance(c, dict):
                        continue
                    if credential in (c.get("id"), c.get("value"), c.get("token")):
                        if c.get("status") in (None, "active", True):
                            ok = True
                            break
            if not ok:
                e = _err("UNAUTHORIZED", "Invalid credential.")
                _log("error", e["error"], cred_used=credential)
                return e
    except Exception:
        # If auth store is malformed, don't brick the service: treat as ambient.
        pass

    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    for r in sessions:
        if isinstance(r, dict) and r.get("session_type") == sessionType and r.get("external_id") == externalId:
            sess = r
            break

    if sess is None:
        # Per audit: do not fail due to wrong context resolution; just not found.
        e = _err("NOT_FOUND", "Session not found.")
        _log("error", e["error"], cred_used=credential)
        return e

    out = {"session": sess}

    if "latest_events" in include:
        events = _load("session_events.json")
        if not isinstance(events, list):
            events = []
        sess_events = [e for e in events if isinstance(e, dict) and e.get("session_id") == sess.get("id")]
        sess_events.sort(key=lambda x: (x.get("sequence_number") if isinstance(x.get("sequence_number"), int) else 10**18))
        if eventsLimit is not None:
            sess_events = sess_events[-eventsLimit:]
        out["latest_events"] = sess_events

    if "personas" in include:
        prs = _load("collaboration_personas.json")
        if not isinstance(prs, list):
            prs = []
        out["personas"] = [p for p in prs if isinstance(p, dict) and p.get("session_id") == sess.get("id")]

    if "decision_components" in include:
        comps = _load("decision_components.json")
        if not isinstance(comps, list):
            comps = []
        out["decision_components"] = [c for c in comps if isinstance(c, dict) and c.get("session_id") == sess.get("id")]

    if "scientific_artifacts" in include:
        arts = _load("scientific_artifacts.json")
        if not isinstance(arts, list):
            arts = []
        out["scientific_artifacts"] = [a for a in arts if isinstance(a, dict) and a.get("session_id") == sess.get("id")]

    # Metadata envelope
    out["meta"] = {"included": include, "timestamp": now}

    _log("ok", extra={"session_id": sess.get("id"), "session_type": sessionType}, cred_used=credential)
    return out

def updatesession(
    credential,
    sessionType,
    externalId,
    title=None,
    iteration=None,
    stage=None,
    status=None,
    nextActionNeeded=None,
    contextText=None,
    stakeholders=None,
    constraintsText=None,
    timeHorizon=None,
    riskTolerance=None,
    analysisType=None,
    overallConfidence=None,
    uncertaintyAreas=None,
    recommendedApproach=None,
    diagramType=None,
    finalText=None,
    **_extra,
):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request logging / rate limiting
    logs_name = "request_logs.json"
    logs = _load(logs_name)
    if not isinstance(logs, list):
        logs = []
    window_sec = 60
    max_per_window = 120
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential") != credential:
            continue
        ts = r.get("created_at") or r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - dt).total_seconds() <= window_sec:
            recent += 1
    if recent >= max_per_window:
        logs.append(
            {
                "id": f"rl_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("RATE_LIMIT", "Too many requests in a short time window.")

    # Validate inputs
    if not isinstance(credential, str) or not credential.strip():
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "credential must be a non-empty string.")
    valid_session_types = {
        "sequential_thinking",
        "collaborative_reasoning",
        "decision_framework",
        "metacognitive_monitoring",
        "scientific_method",
        "structured_argumentation",
        "visual_reasoning",
    }
    if sessionType not in valid_session_types:
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "Invalid sessionType.", allowed=sorted(valid_session_types))
    if not isinstance(externalId, str) or not externalId.strip():
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "externalId must be a non-empty string.")

    if iteration is not None and (not isinstance(iteration, int) or iteration < 0):
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0.")
    if nextActionNeeded is not None and not isinstance(nextActionNeeded, bool):
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "nextActionNeeded must be a boolean.")
    if stakeholders is not None:
        if not isinstance(stakeholders, list) or any((not isinstance(x, str)) for x in stakeholders):
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "updatesession",
                    "credential": credential,
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "stakeholders must be an array of strings.")
    if constraintsText is not None and not isinstance(constraintsText, str):
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "constraintsText must be a string.")
    if riskTolerance is not None and riskTolerance not in ("risk-averse", "risk-neutral", "risk-seeking"):
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "Invalid riskTolerance.")
    if analysisType is not None and analysisType not in ("pros-cons", "weighted-criteria", "decision-tree", "expected-value", "scenario-analysis"):
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "Invalid analysisType.")
    if overallConfidence is not None:
        if not (isinstance(overallConfidence, int) or isinstance(overallConfidence, float)) or overallConfidence < 0 or overallConfidence > 1:
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "updatesession",
                    "credential": credential,
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "overallConfidence must be within [0,1].")
        overallConfidence = float(overallConfidence)
    if uncertaintyAreas is not None:
        if not isinstance(uncertaintyAreas, list) or any((not isinstance(x, str) or not x.strip()) for x in uncertaintyAreas):
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "updatesession",
                    "credential": credential,
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "uncertaintyAreas must be an array of non-empty strings.")
    if diagramType is not None and diagramType not in ("graph", "flowchart", "stateDiagram", "conceptMap", "treeDiagram", "custom"):
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "Invalid diagramType.")

    allowed_status = {"active", "paused", "completed", "archived"}
    if status is not None and status not in allowed_status:
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(allowed_status))

    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Upsert by (session_type, external_id) with uniqueness enforced
    existing_idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("session_type") == sessionType and s.get("external_id") == externalId:
            existing_idx = i
            break

    transitions = {
        "active": {"paused", "completed", "archived"},
        "paused": {"active", "archived"},
        "completed": {"archived"},
        "archived": set(),
    }

    if existing_idx is None:
        # Create new session row
        new_id = f"rs_{uuid.uuid4().hex}"
        new_status = status or "active"
        if new_status not in allowed_status:
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "updatesession",
                    "credential": credential,
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "Invalid status.")
        row = {
            "id": new_id,
            "session_type": sessionType,
            "external_id": externalId,
            "title": title if title is not None else None,
            "iteration": iteration if iteration is not None else 0,
            "stage": stage if stage is not None else None,
            "status": new_status,
            "next_action_needed": nextActionNeeded if nextActionNeeded is not None else False,
            "context_text": contextText if contextText is not None else None,
            "stakeholders": stakeholders if stakeholders is not None else None,
            "constraints_text": [constraintsText] if isinstance(constraintsText, str) else None,
            "time_horizon": timeHorizon if timeHorizon is not None else None,
            "risk_tolerance": riskTolerance if riskTolerance is not None else None,
            "analysis_type": analysisType if analysisType is not None else None,
            "overall_confidence": overallConfidence if overallConfidence is not None else None,
            "uncertainty_areas": uncertaintyAreas if uncertaintyAreas is not None else None,
            "recommended_approach": recommendedApproach if recommendedApproach is not None else None,
            "diagram_type": diagramType if diagramType is not None else None,
            "final_text": finalText if finalText is not None else None,
            "created_at": now,
            "updated_at": now,
        }
        # constraints: iteration >=0 already checked; next_action_needed bool already checked
        sessions.append(row)
        _save("reasoning_sessions.json", sessions)

        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "OK",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return {"session": row, "created": True}

    # Update existing
    row = sessions[existing_idx]
    if not isinstance(row, dict):
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("NOT_FOUND", "Session not found.")

    if status is not None and status != row.get("status"):
        cur = row.get("status")
        if cur not in transitions:
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "updatesession",
                    "credential": credential,
                    "status": "INVALID_TRANSITION",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
            )
            _save(logs_name, logs)
            return _err("INVALID_TRANSITION", "Current session status is invalid.")
        if status not in transitions[cur]:
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "updatesession",
                    "credential": credential,
                    "status": "INVALID_TRANSITION",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
            )
            _save(logs_name, logs)
            return _err("INVALID_TRANSITION", f"Illegal transition from {cur} to {status}.", from_status=cur, to_status=status)

    # Apply updates (mutable fields)
    changed = False

    def _set(k, v):
        nonlocal changed
        if row.get(k) != v:
            row[k] = v
            changed = True

    if title is not None:
        if not isinstance(title, str):
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatesession", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "title must be a string.")
        _set("title", title)

    if iteration is not None:
        _set("iteration", iteration)
    if stage is not None:
        if not isinstance(stage, str):
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatesession", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "stage must be a string.")
        _set("stage", stage)
    if status is not None:
        _set("status", status)
    if nextActionNeeded is not None:
        _set("next_action_needed", nextActionNeeded)
    if contextText is not None:
        if not isinstance(contextText, str):
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatesession", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "contextText must be a string.")
        _set("context_text", contextText)
    if stakeholders is not None:
        _set("stakeholders", stakeholders)
    if constraintsText is not None:
        # stored as array per schema; API provides string => store single-item array
        _set("constraints_text", [constraintsText])
    if timeHorizon is not None:
        if not isinstance(timeHorizon, str):
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatesession", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "timeHorizon must be a string.")
        _set("time_horizon", timeHorizon)
    if riskTolerance is not None:
        _set("risk_tolerance", riskTolerance)
    if analysisType is not None:
        _set("analysis_type", analysisType)
    if overallConfidence is not None:
        _set("overall_confidence", overallConfidence)
    if uncertaintyAreas is not None:
        _set("uncertainty_areas", uncertaintyAreas)
    if recommendedApproach is not None:
        if not isinstance(recommendedApproach, str):
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatesession", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "recommendedApproach must be a string.")
        _set("recommended_approach", recommendedApproach)
    if diagramType is not None:
        _set("diagram_type", diagramType)
    if finalText is not None:
        if not isinstance(finalText, str):
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatesession", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "finalText must be a string.")
        _set("final_text", finalText)

    if not changed:
        # No success without effect: but upsert/update endpoint should be idempotent.
        # Here we return current session without writing.
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "updatesession",
                "credential": credential,
                "status": "OK",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return {"session": row, "updated": False}

    row["updated_at"] = now
    sessions[existing_idx] = row
    _save("reasoning_sessions.json", sessions)

    logs.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "updatesession",
            "credential": credential,
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
    )
    _save(logs_name, logs)
    return {"session": row, "updated": True}

def listevents(
    credential,
    sessionType,
    externalId,
    eventType=None,
    toolName=None,
    iteration=None,
    afterSequenceNumber=None,
    limit=None,
    cursor=None,
    order=None,
    **_extra,
):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request logging / rate limiting
    logs_name = "request_logs.json"
    logs = _load(logs_name)
    if not isinstance(logs, list):
        logs = []
    window_sec = 60
    max_per_window = 120
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential") != credential:
            continue
        ts = r.get("created_at") or r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - dt).total_seconds() <= window_sec:
            recent += 1
    if recent >= max_per_window:
        logs.append(
            {
                "id": f"rl_{int(time.time()*1000)}",
                "endpoint": "listevents",
                "credential": credential,
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save(logs_name, logs)
        return _err("RATE_LIMIT", "Too many requests in a short time window.")

    # Validate
    if not isinstance(credential, str) or not credential.strip():
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "credential must be a non-empty string.")
    valid_session_types = {
        "sequential_thinking",
        "collaborative_reasoning",
        "decision_framework",
        "metacognitive_monitoring",
        "scientific_method",
        "structured_argumentation",
        "visual_reasoning",
    }
    if sessionType not in valid_session_types:
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "Invalid sessionType.", allowed=sorted(valid_session_types))
    if not isinstance(externalId, str) or not externalId.strip():
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "externalId must be a non-empty string.")

    allowed_event_types = {
        "thought",
        "revision",
        "branch",
        "model_application",
        "pattern_application",
        "paradigm_application",
        "debugging_application",
        "contribution",
        "decision_update",
        "monitoring_update",
        "scientific_update",
        "argument",
        "diagram_operation",
    }
    if eventType is not None and eventType not in allowed_event_types:
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "Invalid eventType.", allowed=sorted(allowed_event_types))
    if toolName is not None and not isinstance(toolName, str):
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "toolName must be a string.")
    if iteration is not None and (not isinstance(iteration, int) or iteration < 0):
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0.")
    if afterSequenceNumber is not None and (not isinstance(afterSequenceNumber, int) or afterSequenceNumber < 0):
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "afterSequenceNumber must be an integer >= 0.")
    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "limit must be an integer within [1,500].")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'.")
    if cursor is not None and not isinstance(cursor, str):
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Resolve session
    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("session_type") == sessionType and s.get("external_id") == externalId:
            session = s
            break
    if session is None:
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("NOT_FOUND", "Session not found.")

    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []

    evs = [e for e in events if isinstance(e, dict) and e.get("session_id") == session.get("id")]

    if eventType is not None:
        evs = [e for e in evs if e.get("event_type") == eventType]
    if toolName is not None:
        evs = [e for e in evs if e.get("tool_name") == toolName]
    if iteration is not None:
        evs = [e for e in evs if e.get("iteration") == iteration]

    # Cursor: base64 of JSON {"seq": <int>} meaning "start after this seq in the requested order"
    cursor_seq = None
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("seq"), int) and obj["seq"] >= 0:
                cursor_seq = obj["seq"]
            else:
                raise ValueError("bad cursor")
        except Exception:
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "listevents", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Apply afterSequenceNumber and cursor_seq
    if order == "asc":
        evs.sort(key=lambda x: x.get("sequence_number") if isinstance(x.get("sequence_number"), int) else 10**18)
        threshold = 0
        if afterSequenceNumber is not None:
            threshold = max(threshold, afterSequenceNumber)
        if cursor_seq is not None:
            threshold = max(threshold, cursor_seq)
        evs = [e for e in evs if isinstance(e.get("sequence_number"), int) and e["sequence_number"] > threshold]
    else:
        evs.sort(key=lambda x: x.get("sequence_number") if isinstance(x.get("sequence_number"), int) else -1, reverse=True)
        threshold = None
        # for desc, "cursor_seq" means "return events with sequence_number < cursor_seq"
        # also interpret afterSequenceNumber as still ">"
        if afterSequenceNumber is not None:
            evs = [e for e in evs if isinstance(e.get("sequence_number"), int) and e["sequence_number"] > afterSequenceNumber]
        if cursor_seq is not None:
            evs = [e for e in evs if isinstance(e.get("sequence_number"), int) and e["sequence_number"] < cursor_seq]

    total = len(evs)
    page = evs[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last_seq = page[-1].get("sequence_number")
        if isinstance(last_seq, int):
            tok = base64.urlsafe_b64encode(json.dumps({"seq": last_seq}).encode("utf-8")).decode("utf-8").rstrip("=")
            next_cursor = tok

    logs.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "listevents",
            "credential": credential,
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
    )
    _save(logs_name, logs)
    return {
        "events": page,
        "pagination": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "order": order},
    }

