        if communicationStyle is None or communicationTone is None:
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("VALIDATION_ERROR", "communicationStyle and communicationTone are required when creating a persona.")

        row = {
            "id": f"cp_{uuid.uuid4().hex}",
            "session_id": sess.get("id"),
            "external_persona_id": externalPersonaId,
            "name": name,
            "expertise": expertise if expertise is not None else [],
            "background": background if background is not None else "",
            "perspective": perspective if perspective is not None else "",
            "biases": biases if biases is not None else [],
            "communication_style": communicationStyle,
            "communication_tone": communicationTone,
            "status": status if status is not None else "active",
            "created_at": now,
            "updated_at": now,
        }
        personas.append(row)
        _save("collaboration_personas.json", personas)

        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return {"persona": row, "created": True}

    row = personas[existing_idx]
    if not isinstance(row, dict):
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("NOT_FOUND", "Persona not found.")

    # status transition validation
    if status is not None and status != row.get("status"):
        cur = row.get("status")
        if cur not in transitions or status not in transitions[cur]:
            logs.append(
                {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "INVALID_TRANSITION", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
            )
            _save(logs_name, logs)
            return _err("INVALID_TRANSITION", f"Illegal transition from {cur} to {status}.", from_status=cur, to_status=status)

    changed = False

    def _set(k, v):
        nonlocal changed
        if row.get(k) != v:
            row[k] = v
            changed = True

    _set("name", name)
    if expertise is not None:
        _set("expertise", expertise)
    if background is not None:
        _set("background", background)
    if perspective is not None:
        _set("perspective", perspective)
    if biases is not None:
        _set("biases", biases)
    if communicationStyle is not None:
        _set("communication_style", communicationStyle)
    if communicationTone is not None:
        _set("communication_tone", communicationTone)
    if status is not None:
        _set("status", status)

    # Enforce non-empty comm fields constraint
    if not isinstance(row.get("communication_style"), str) or not row["communication_style"].strip():
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "communicationStyle must be non-empty.")
    if not isinstance(row.get("communication_tone"), str) or not row["communication_tone"].strip():
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return _err("VALIDATION_ERROR", "communicationTone must be non-empty.")

    if not changed:
        # idempotent return
        logs.append(
            {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
        )
        _save(logs_name, logs)
        return {"persona": row, "updated": False}

    row["updated_at"] = now
    personas[existing_idx] = row
    _save("collaboration_personas.json", personas)

    logs.append(
        {"id": f"req_{int(time.time()*1000)}", "endpoint": "updatepersona", "credential": credential, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "created_at": now}
    )
    _save(logs_name, logs)
    return {"persona": row, "updated": True}

def whoami(credential, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0186000" if __import__("os").path.isdir("./environment_mix/0186000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str): return None
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, error=None, extra=None, cred_used=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "ct_req_" + uuid.uuid4().hex,
            "endpoint": "whoami",
            "status": status,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if cred_used is not None:
            row["credential"] = cred_used
        if extra and isinstance(extra, dict):
            row.update(extra)
        if error and isinstance(error, dict):
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(cred_used=None):
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rlm = limits.get("rate_limit_per_minute")
        qpd = limits.get("quota_per_day")
        if isinstance(rlm, int) and rlm >= 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if cred_used is not None and r.get("credential") not in (None, cred_used):
                    continue
                dt = _parse_ts(r.get("timestamp"))
                if dt and dt >= cutoff:
                    cnt += 1
            if cnt >= rlm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(qpd, int) and qpd >= 0:
            cutoff = now_dt - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if cred_used is not None and r.get("credential") not in (None, cred_used):
                    continue
                dt = _parse_ts(r.get("timestamp"))
                if dt and dt >= cutoff:
                    cnt += 1
            if cnt >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # validate
    if not isinstance(credential, str) or not credential:
        e = _err("VALIDATION_ERROR", "credential must be a non-empty string")
        _log("error", error=e["error"])
        return e

    # limits before doing work (still must log)
    limit_err = _enforce_limits(cred_used=credential)
    if limit_err:
        _log("error", error=limit_err["error"], cred_used=credential)
        return limit_err

    # authenticate by id or client-visible value fields (never by hash)
    creds = _load("credentials.json")
    accounts = _load("accounts.json")
    workspaces = _load("workspaces.json")

    principal = None
    if isinstance(creds, list) and len(creds) > 0:
        for c in creds:
            if not isinstance(c, dict):
                continue
            if credential in (c.get("id"), c.get("value"), c.get("token"), c.get("key")):
                # ensure active parent(s) if present
                acct_ok = True
                ws_ok = True
                acct_id = c.get("account_id") or c.get("accountId")
                ws_id = c.get("workspace_id") or c.get("workspaceId")
                if acct_id and isinstance(accounts, list) and len(accounts) > 0:
                    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == acct_id), None)
                    if acct is None or acct.get("status") not in (None, "active"):
                        acct_ok = False
                if ws_id and isinstance(workspaces, list) and len(workspaces) > 0:
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
                    if ws is None or ws.get("status") not in (None, "active"):
                        ws_ok = False
                if acct_ok and ws_ok:
                    principal = c
                    break
        if principal is None:
            e = _err("UNAUTHORIZED", "Invalid credential")
            _log("error", error=e["error"], cred_used=credential)
            return e
    else:
        # If store doesn't model credentials, accept any non-empty credential per contract environment.
        principal = {"id": None, "value": credential}

    # compute usage from request logs
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    last_min_cutoff = now_dt - datetime.timedelta(seconds=60)
    last_day_cutoff = now_dt - datetime.timedelta(days=1)
    per_min = 0
    per_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential") not in (None, credential):
            continue
        dt = _parse_ts(r.get("timestamp"))
        if not dt:
            continue
        if dt >= last_min_cutoff:
            per_min += 1
        if dt >= last_day_cutoff:
            per_day += 1

    limits = _load("service_limits.json")
    if not isinstance(limits, dict):
        limits = {}

    resp = {
        "identity": {
            "credential_id": principal.get("id"),
            "credential_value": credential,
            "account_id": principal.get("account_id") or principal.get("accountId"),
            "workspace_id": principal.get("workspace_id") or principal.get("workspaceId"),
        },
        "scopes": principal.get("scopes") if isinstance(principal.get("scopes"), list) else [],
        "usage": {
            "requests_last_minute": per_min,
            "requests_last_24h": per_day,
        },
        "limits": {
            "rate_limit_per_minute": limits.get("rate_limit_per_minute"),
            "quota_per_day": limits.get("quota_per_day"),
        }
    }
    _log("ok", extra={"requests_last_minute": per_min, "requests_last_24h": per_day}, cred_used=credential)
    return resp
